insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('back-to-work-after-the-long-weekend-inbox-plan-sheet', 'Back to Work After the Long Weekend Inbox Plan Sheet', 'worksheet'::resource_kind, 'A first-hour plan for the inbox that filled up over a long weekend, sorted before a single reply is written.', 'Use it to turn a dreaded inbox into three piles and one next action.', array['Adults']::text[], '15 minutes on the first morning back', 'The first day back after a long weekend often goes to reading the same messages three times. The sheet asks the client to count the unread pile once, sort it into answer today, answer this week and only read, and name the single reply that matters most. The last box is the hour the inbox closes so the rest of the day can start. Watch for the client who sorts everything into today; the this-week pile is where the practice is.', '[{"id": "f0", "type": "textarea", "label": "How many unread messages are waiting, counted once:"}, {"id": "f1", "type": "textarea", "label": "The ones I will answer today (names or subjects):"}, {"id": "f2", "type": "textarea", "label": "The ones that can wait until later this week:"}, {"id": "f3", "type": "textarea", "label": "The ones I only need to read:"}, {"id": "f4", "type": "textarea", "label": "The single reply that matters most, and the first sentence of it:"}, {"id": "f5", "type": "textarea", "label": "The time I will close the inbox and start the rest of the day:"}]'::jsonb, array['work', 'planning', 'stress']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('use-it-or-lose-it-vacation-days-decision-sheet', 'Use-It-or-Lose-It Vacation Days Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for the vacation days that expire at year end and the reasons the client has not taken them.', 'Use it to get the client''s remaining days onto the calendar before they vanish.', array['Adults']::text[], '20 minutes', 'Unused days usually sit behind a story about being needed or a dread of the return pile. The sheet counts the days left, names the story that has kept them untaken, and books them in a shape the client can defend: a long weekend, a midweek day, a block. The last box is the sentence the client will use when asked to move them. Watch for the client who books the days and then works through them; a plan for the first morning off is worth a line.', '[{"id": "f0", "type": "textarea", "label": "How many days I have left, and the date they expire:"}, {"id": "f1", "type": "textarea", "label": "The reason I have not taken them, in one honest sentence:"}, {"id": "f2", "type": "textarea", "label": "What would actually happen at work if I took them:"}, {"id": "f3", "type": "textarea", "label": "The dates I will book, and the shape of each (long weekend, midweek, block):"}, {"id": "f4", "type": "textarea", "label": "What I will say if someone asks me to move them:"}, {"id": "f5", "type": "textarea", "label": "What I will do on the first morning off, so it is not work:"}]'::jsonb, array['work', 'rest', 'decisions']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('health-spending-account-deadline-balance-plan-sheet', 'Health Spending Account Deadline Balance Plan Sheet', 'worksheet'::resource_kind, 'A plan for the balance left in a health spending account before the deadline, decided once instead of fretted about nightly.', 'Use it to turn a vague year-end deadline into a short list and a date.', array['Adults']::text[], '20 minutes with the account statement open', 'A balance that must be spent by a deadline is a small money worry that grows in December. The sheet asks for the number, the deadline, what the client has been putting off that it could cover, and the appointments or orders that need booking now to land in time. The last box is the date the client will stop thinking about it because it is done. Watch for the client who spends it on something unneeded to make the worry stop; the putting-off list is where the value sits.', '[{"id": "f0", "type": "textarea", "label": "The balance left, and the date it must be used by:"}, {"id": "f1", "type": "textarea", "label": "Care I have been putting off that this could pay for:"}, {"id": "f2", "type": "textarea", "label": "Supplies or orders I actually need that qualify:"}, {"id": "f3", "type": "textarea", "label": "The appointments or orders I must book this week for them to land in time:"}, {"id": "f4", "type": "textarea", "label": "The date it will be settled and I can stop thinking about it:"}]'::jsonb, array['money', 'planning', 'self-care']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('winter-car-emergency-kit-pack-and-peace-of-mind-sheet', 'Winter Car Emergency Kit Pack and Peace of Mind Sheet', 'worksheet'::resource_kind, 'A packing sheet for a winter car kit, built so that the worry about getting stranded has a concrete answer in the trunk.', 'Use it to let a client trade a looping what-if for a packed bag they can point to.', array['Adults', 'Teens']::text[], '30 minutes to pack, then one line per month', 'Winter driving worry often circles the same picture: stranded on a dark road with a dead phone. The sheet turns the picture into a list, a trip to the hall closet, and a bag in the trunk, then asks the client what they will tell their mind the next time the picture shows up. A monthly line checks the bag so it stays an answer. Watch for the client who packs the kit and keeps worrying anyway; the last box is the beginning of that conversation.', '[{"id": "f0", "type": "textarea", "label": "The scene my mind shows me about winter driving:"}, {"id": "f1", "type": "textarea", "label": "What is already in the car that would help:"}, {"id": "f2", "type": "textarea", "label": "What I will add this week (blanket, charger, water, scraper, flashlight, snacks):"}, {"id": "f3", "type": "textarea", "label": "Who I would call, and the number saved where I can find it:"}, {"id": "f4", "type": "textarea", "label": "What I will say to my mind when the scene shows up now that the bag is packed:"}, {"id": "f5", "type": "textarea", "label": "The day each month I will check the kit:"}]'::jsonb, array['worry', 'planning', 'safety']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('year-end-charity-giving-decision-sheet', 'Year-End Charity Giving Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for the December asks to give, with a total chosen first and the guilt about every other envelope named.', 'Use it to help a client give on purpose and say no to the rest without a week of guilt.', array['Adults']::text[], '20 minutes before the asks arrive', 'December brings more requests to give than anyone can answer, and guilt does the deciding if nothing else does. The sheet sets the total first, names the one or two causes that match what the client cares about, and writes the sentence for every other ask, including the one at the register. Watch for the client whose total is set by shame rather than their budget, and for the one who gives nothing because they cannot give to everyone.', '[{"id": "f0", "type": "textarea", "label": "The total I can give this season without strain:"}, {"id": "f1", "type": "textarea", "label": "The one or two causes that matter most to me, and why:"}, {"id": "f2", "type": "textarea", "label": "How I will split the total between them:"}, {"id": "f3", "type": "textarea", "label": "What I will say to every other ask, including at the register:"}, {"id": "f4", "type": "textarea", "label": "The guilt thought that shows up when I say no, and my answer to it:"}]'::jsonb, array['money', 'values', 'boundaries']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('friend-canceled-plans-twice-mind-reading-sheet', 'Friend Canceled Plans Twice Mind Reading Sheet', 'cbt'::resource_kind, 'A mind-reading record for the moment a friend cancels a second time and the client is sure they know why.', 'Use it to separate what the client knows about the cancellation from what they have filled in.', array['Adults', 'Teens']::text[], '15 minutes', 'Two cancellations in a row read as a verdict to many clients: they are tired of me, they found better people. The sheet records the actual message word for word, the mind-read beneath it, and the facts that would be true if the mind-read were right. Then it lists three other reasons a friend cancels twice and the one question that would settle it. Watch for the client who will not ask because asking feels needy; that is the next session''s work.', '[{"id": "f0", "type": "textarea", "label": "What my friend actually wrote or said, word for word:"}, {"id": "f1", "type": "textarea", "label": "What I decided it meant about how they feel about me:"}, {"id": "f2", "type": "textarea", "label": "What I would expect to see if that were true, and whether I have seen it:"}, {"id": "f3", "type": "textarea", "label": "Three other reasons a person cancels twice in a row:"}, {"id": "f4", "type": "textarea", "label": "The question I could ask that would settle it:"}, {"id": "f5", "type": "textarea", "label": "How I will feel if the real reason is one of the three:"}]'::jsonb, array['mind reading', 'core CBT', 'relationships']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('one-missed-workout-means-a-lost-week-all-or-nothing-sheet', 'One Missed Workout Means a Lost Week All-or-Nothing Sheet', 'cbt'::resource_kind, 'An all-or-nothing thinking sheet for the skipped workout that turns into a written-off week.', 'Use it to show a client the middle ground between a perfect week and a lost one.', array['Adults', 'Teens']::text[], '10 minutes on the day of the skip', 'A skipped session becomes a lost week when the only categories are perfect and ruined. The sheet records the skip, the sentence that followed it, and then asks the client to write the week as a scale from zero to ten and mark where it actually sits. The last box is the smallest movement that would count tomorrow. Watch for the client who scores the week a zero out of loyalty to the rule; ask what a nine would have looked like.', '[{"id": "f0", "type": "textarea", "label": "What I skipped, and the sentence my mind said right after:"}, {"id": "f1", "type": "textarea", "label": "The two categories my mind is using (perfect and what?):"}, {"id": "f2", "type": "textarea", "label": "The week as a scale from 0 to 10, and where it honestly sits:"}, {"id": "f3", "type": "textarea", "label": "What I did this week that the all-or-nothing rule does not count:"}, {"id": "f4", "type": "textarea", "label": "The smallest movement tomorrow that would count:"}, {"id": "f5", "type": "textarea", "label": "The sentence I will use the next time I skip once:"}]'::jsonb, array['all-or-nothing', 'thinking traps', 'habits']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('leave-early-without-the-full-goodbye-round-experiment-sheet', 'Leave Early Without the Full Goodbye Round Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment in leaving a gathering with one quiet goodbye to the host instead of a round of every guest.', 'Use it to test the prediction that a short exit is rude and will be held against the client.', array['Adults']::text[], 'One gathering, plus 10 minutes after', 'Some clients stay an hour past tired because leaving means a goodbye tour of every guest. The sheet sets the prediction, the exact plan (thank the host, one wave, out), and the signs the client will watch for afterward. The after section records what actually came back, which is usually nothing or a text saying good to see you. Watch for the client who leaves early and then apologizes to everyone the next day; that is a safety behavior worth naming.', '[{"id": "f0", "type": "textarea", "label": "The gathering, and the time I will leave:"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen if I only say goodbye to the host:"}, {"id": "f2", "type": "textarea", "label": "How sure I am (0 to 100), and what I would see if I were right:"}, {"id": "f3", "type": "textarea", "label": "My exact exit plan, step by step:"}, {"id": "f4", "type": "textarea", "label": "What actually happened, and what anyone said afterward:"}, {"id": "f5", "type": "textarea", "label": "What this tells me about the rule I was following:"}]'::jsonb, array['behavioral experiment', 'core CBT', 'social skills']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('dread-at-the-desk-means-trouble-emotional-reasoning-sheet', 'Dread at the Desk Means Trouble Emotional Reasoning Sheet', 'cbt'::resource_kind, 'An emotional reasoning sheet for the Monday dread that gets read as proof that something at work is wrong.', 'Use it to help a client separate a feeling from the forecast it seems to carry.', array['Adults']::text[], '10 minutes at the desk', 'Dread on a quiet morning gets taken as information: if I feel this, something must be coming. The sheet records the feeling and its strength, the conclusion the client drew from it, and then the actual evidence for and against anything being wrong. The last box asks what the dread predicted last time and whether it came true. Watch for the client who finds one true prediction in a hundred and keeps the rule.', '[{"id": "f0", "type": "textarea", "label": "The feeling, and how strong it is right now (0 to 10):"}, {"id": "f1", "type": "textarea", "label": "What I decided it means is coming:"}, {"id": "f2", "type": "textarea", "label": "Evidence that something is actually wrong, from facts not feelings:"}, {"id": "f3", "type": "textarea", "label": "Evidence that nothing is wrong, or nothing unusual:"}, {"id": "f4", "type": "textarea", "label": "The last three times I felt this: what did it predict, and did it come true?"}, {"id": "f5", "type": "textarea", "label": "What I will do with the feeling now, without obeying it:"}]'::jsonb, array['emotional reasoning', 'thinking traps', 'work']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('napping-means-i-am-lazy-labeling-sheet', 'Napping Means I Am Lazy Labeling Sheet', 'cbt'::resource_kind, 'A labeling sheet for the afternoon nap that becomes a verdict on the client''s whole character.', 'Use it to replace a one-word label with a description of what actually happened.', array['Adults', 'Teens']::text[], '10 minutes after the nap', 'A nap is a nap until the mind calls the person who took it lazy. The sheet records the label, what the client actually did today beside the nap, and what the label leaves out. It asks what the client would say about a friend who napped under the same conditions and writes the description that replaces the label. Watch for the client who accepts the kinder description for the friend and not themselves; that gap is worth sitting in.', '[{"id": "f0", "type": "textarea", "label": "The label my mind gave me, word for word:"}, {"id": "f1", "type": "textarea", "label": "What actually happened (how long, after what kind of day):"}, {"id": "f2", "type": "textarea", "label": "What I did today that the label leaves out:"}, {"id": "f3", "type": "textarea", "label": "What I would say about a friend who did the same thing:"}, {"id": "f4", "type": "textarea", "label": "The description that replaces the label, in plain words:"}]'::jsonb, array['labeling', 'thinking traps', 'self-criticism']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('thoughts-as-flyers-tucked-under-the-windshield-wiper-page', 'Thoughts as Flyers Tucked Under the Windshield Wiper Page', 'act'::resource_kind, 'A defusion page that treats intrusive judgments as flyers left on the car, there to be noticed and set aside, not read and obeyed.', 'Use it to give a client a picture for letting a thought be present without engaging it.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'Nobody argues with a flyer under the wiper; they notice it, maybe glance at it, and drive on. The page asks the client to write their most frequent judgments as flyers, headline and all, then practice the glance and the drive. It records what each flyer wants them to do and what they did instead. Watch for the client who reads every flyer to the end before setting it down; that reading is the fusion the page is for.', '[{"id": "f0", "type": "textarea", "label": "The thoughts that keep showing up, written as flyer headlines:"}, {"id": "f1", "type": "textarea", "label": "What each flyer wants me to do (argue, check, give up, hide):"}, {"id": "f2", "type": "textarea", "label": "What I notice in my body when a flyer appears:"}, {"id": "f3", "type": "textarea", "label": "A moment this week when I glanced and drove on anyway:"}, {"id": "f4", "type": "textarea", "label": "What I was heading toward when I did:"}]'::jsonb, array['defusion', 'core ACT', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('values-while-returning-the-shopping-cart-page', 'Values While Returning the Shopping Cart Page', 'act'::resource_kind, 'A values page that uses the smallest unwatched act, walking the cart back, to find what the client wants to stand for.', 'Use it to let a client locate their values in an act nobody will see or praise.', array['Adults', 'Teens']::text[], '10 minutes, then notice it once a week', 'The cart return is a tiny decision made with nobody watching, which makes it a clean place to look at values. The page asks what the client does with the cart, what they would like to do, and what quality the gap is about: care, ease, fairness, not being told what to do. It then finds two other unwatched moments in the week where the same quality could show. Watch for the client who turns this into a scold; it is an inquiry, not a rule.', '[{"id": "f0", "type": "textarea", "label": "What I usually do with the cart, and what I would like to do:"}, {"id": "f1", "type": "textarea", "label": "The quality the choice is about for me (care, ease, fairness, something else):"}, {"id": "f2", "type": "textarea", "label": "Where else that quality shows up when no one is watching:"}, {"id": "f3", "type": "textarea", "label": "Two unwatched moments this week where I could act on it:"}, {"id": "f4", "type": "textarea", "label": "What it felt like when I did, with nobody to notice:"}]'::jsonb, array['values', 'core ACT', 'committed action']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('willing-to-eat-lunch-alone-in-the-break-room-page', 'Willing to Eat Lunch Alone in the Break Room Page', 'act'::resource_kind, 'A willingness page for the discomfort of eating alone where coworkers can see, chosen rather than avoided.', 'Use it to help a client make room for the exposed feeling while doing an ordinary thing.', array['Adults']::text[], 'One lunch, plus 10 minutes after', 'Eating at the desk or in the car to avoid being seen alone costs a client their break and sometimes their colleagues. The page names the feelings that would show up at the break-room table, what the client is willing to have in exchange for a real lunch, and the one value that makes it worth it. It records the lunch afterward in plain terms. Watch for the client who brings a phone as a shield the whole time; willingness with a prop is a fine first step, named as such.', '[{"id": "f0", "type": "textarea", "label": "What I usually do at lunch, and what it costs me:"}, {"id": "f1", "type": "textarea", "label": "What I expect to feel at the break-room table, in my body and in my head:"}, {"id": "f2", "type": "textarea", "label": "What I am willing to have, in exchange for what:"}, {"id": "f3", "type": "textarea", "label": "What matters to me about this (rest, belonging, not hiding, something else):"}, {"id": "f4", "type": "textarea", "label": "What the lunch was actually like, in plain words:"}]'::jsonb, array['willingness', 'core ACT', 'avoidance']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('warm-mug-between-both-hands-present-moment-page', 'Warm Mug Between Both Hands Present Moment Page', 'act'::resource_kind, 'A present-moment page built on holding a hot drink with both hands for sixty seconds before the first sip.', 'Use it to give a client an anchor they already reach for several times a day.', array['Adults', 'Teens']::text[], 'One minute, several times a day', 'Most clients already hold a warm mug several times a day without noticing it. The page turns that into a one-minute anchor: both hands, the heat, the weight, the steam, the first sip taken on purpose. It records where the mind went and what it was like to come back. Watch for the client who turns the minute into a test of focus; wandering and returning is the whole exercise.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what I was drinking:"}, {"id": "f1", "type": "textarea", "label": "What I noticed with both hands around the mug (heat, weight, texture):"}, {"id": "f2", "type": "textarea", "label": "Where my mind went during the minute:"}, {"id": "f3", "type": "textarea", "label": "What it was like to come back to the mug:"}, {"id": "f4", "type": "textarea", "label": "Where in my day the mug minute could sit each time:"}]'::jsonb, array['mindfulness', 'core ACT', 'present moment']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('check-the-facts-on-the-boss-s-one-word-reply-card', 'Check the Facts on the Boss''s One-Word Reply Card', 'dbt'::resource_kind, 'A Check the Facts card for the moment a manager answers a careful message with a single word.', 'Use it to help a client find the emotion the one-word reply set off and test whether it fits the facts.', array['Adults']::text[], '10 minutes', 'A reply that says only fine or ok can set off a whole afternoon of dread. The card walks the client through the prompting event, the interpretation, the emotion and its intensity, and then the facts: what is known about how this manager writes, what the message actually asked for, and what the threat would be if the fear were true. The last box is whether the emotion fits the facts and what to do either way. Watch for the client who wants proof the boss is pleased; the card settles for fits or does not.', '[{"id": "f0", "type": "textarea", "label": "The message I sent, and the reply I got, word for word:"}, {"id": "f1", "type": "textarea", "label": "The emotion it set off, and how strong (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I decided the reply meant:"}, {"id": "f3", "type": "textarea", "label": "What I know about how this person usually writes:"}, {"id": "f4", "type": "textarea", "label": "If my fear were true, what would actually happen, and could I cope with it?"}, {"id": "f5", "type": "textarea", "label": "Does the emotion fit the facts? What I will do now either way:"}]'::jsonb, array['check the facts', 'core DBT', 'work']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-the-sound-of-rain-on-the-roof-card', 'Self-Soothe With the Sound of Rain on the Roof Card', 'dbt'::resource_kind, 'A Self-Soothe card for a rainy evening, using the sound on the roof or window as the single sense to rest in.', 'Use it to give a client a soothing skill that the weather hands them for free.', array['Adults', 'Teens']::text[], 'Ten minutes on a rainy evening', 'Hearing is the sense most clients skip when they self-soothe, and rain is the easiest practice. The card asks the client to sit near a window or under the roof, lights low, and give ten minutes to the sound alone, noticing the rhythm, the gusts, the drips, and bringing the mind back when it leaves. It records the distress before and after and what the skill was like. Watch for the client who scrolls through the ten minutes; one sense at a time is the point.', '[{"id": "f0", "type": "textarea", "label": "Where I sat, and what the rain sounded like at first:"}, {"id": "f1", "type": "textarea", "label": "My distress before (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "What I noticed in the sound as the minutes passed:"}, {"id": "f3", "type": "textarea", "label": "Where my mind went, and what brought it back:"}, {"id": "f4", "type": "textarea", "label": "My distress after (0 to 10), and what the ten minutes were like:"}]'::jsonb, array['self-soothing', 'distress tolerance', 'core DBT']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-canceling-the-coffee-plan-card', 'Opposite Action to Canceling the Coffee Plan Card', 'dbt'::resource_kind, 'An Opposite Action card for the morning the client wants to cancel a coffee with a friend because the mood says stay home.', 'Use it to help a client act against the urge to withdraw when withdrawing does not fit the facts.', array['Adults', 'Teens']::text[], '15 minutes on the morning of the plan', 'The urge to cancel arrives with a convincing case: tired, not up to it, they will not mind. The card names the emotion and its action urge, checks whether the urge fits the facts of the friendship and the day, and then plans the opposite all the way: go, arrive on time, sit facing them, ask one real question. It records the mood before and after. Watch for the client who goes and spends the hour apologizing for being low; the all-the-way part includes the posture and the questions.', '[{"id": "f0", "type": "textarea", "label": "The emotion this morning, and what it is telling me to do:"}, {"id": "f1", "type": "textarea", "label": "Does canceling fit the facts? What would it cost me and the friendship?"}, {"id": "f2", "type": "textarea", "label": "The opposite action, all the way (go, posture, eye contact, one real question):"}, {"id": "f3", "type": "textarea", "label": "My mood before I left (0 to 10):"}, {"id": "f4", "type": "textarea", "label": "My mood on the way home (0 to 10), and what surprised me:"}]'::jsonb, array['opposite action', 'emotion regulation', 'core DBT']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('december-calendar-merge-night-for-partners', 'December Calendar Merge Night for Partners', 'couples'::resource_kind, 'A one-evening ritual for partners to lay both December calendars side by side before the month fills them.', 'Use it to help a couple decide the month together instead of discovering each other''s plans.', array['Couples']::text[], 'One evening before December begins', 'December fights are often calendar fights in disguise: one partner said yes to a party the other did not know about. Both partners bring their own calendar and read it aloud, date by date, while the other writes it on a shared page. Then each names two evenings they want kept empty and one thing they want to do together. Watch for the partner who treats the merge as a review of the other''s choices; the task is to see the month, not to grade it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my December commitments, read aloud date by date:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my December commitments, read aloud date by date:"}, {"id": "f2", "type": "textarea", "label": "Partner A: two evenings I want kept empty, and why:"}, {"id": "f3", "type": "textarea", "label": "Partner B: two evenings I want kept empty, and why:"}, {"id": "f4", "type": "textarea", "label": "One thing we both want to do together this month, and its date:"}, {"id": "f5", "type": "textarea", "label": "The dates we are double-booked, and how we will choose:"}]'::jsonb, array['couples', 'planning', 'holidays']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('rsvp-owner-and-plus-one-check-pact-for-partners', 'RSVP Owner and Plus-One Check Pact for Partners', 'couples'::resource_kind, 'A pact that decides who answers each invitation and how the other partner is asked before a yes goes out.', 'Use it to end the fight where one partner accepted for both without asking.', array['Couples']::text[], '20 minutes', 'An invitation answered for two is a small decision that lands as a large one. Each partner names the times they were signed up without being asked, and how it felt. Then they agree on the rule: who owns which invitations, how the check happens (a text, a question at dinner), and how long the other has to answer before a yes stands. Watch for the partner who wants veto power over every plan; the pact is a check, not a lock.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a time I was signed up without being asked, and how it felt:"}, {"id": "f1", "type": "textarea", "label": "Partner B: a time I was signed up without being asked, and how it felt:"}, {"id": "f2", "type": "textarea", "label": "Which invitations each of us owns (work, family, friends):"}, {"id": "f3", "type": "textarea", "label": "How the check happens before a yes goes out, and how fast the other answers:"}, {"id": "f4", "type": "textarea", "label": "What we say when one of us wants to go and the other does not:"}]'::jsonb, array['couples', 'communication', 'fairness']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('blanket-hog-and-cold-feet-bed-truce-for-partners', 'Blanket Hog and Cold Feet Bed Truce for Partners', 'couples'::resource_kind, 'A practical truce for the small nightly war over covers, cold feet and who gets the warm side of the bed.', 'Use it to settle a nightly irritation that keeps showing up in bigger arguments.', array['Couples']::text[], '15 minutes, then one week to try it', 'Bed battles are low stakes and nightly, which is exactly why they leak into the daytime. Each partner says what they actually need to sleep (more cover, less heat, feet warmed first) without blaming the other. Then they test a fix for a week: two blankets, a heated pad on one side, socks, a bigger duvet. The debrief is one line each. Watch for the couple using the blanket to argue about consideration; name that, then come back to the blanket.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need to fall asleep, said without blame:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need to fall asleep, said without blame:"}, {"id": "f2", "type": "textarea", "label": "The fix we will try for one week:"}, {"id": "f3", "type": "textarea", "label": "Partner A, after the week: what worked, what did not:"}, {"id": "f4", "type": "textarea", "label": "Partner B, after the week: what worked, what did not:"}]'::jsonb, array['couples', 'sleep', 'problem solving']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('year-end-money-review-without-blame-hour-for-partners', 'Year-End Money Review Without Blame Hour for Partners', 'couples'::resource_kind, 'A structured hour for partners to look at the year''s money together, facts first and blame left out of it.', 'Use it to help a couple talk about the year''s spending as a team rather than as prosecutor and defendant.', array['Couples']::text[], 'One hour, with statements and a snack', 'Money reviews go wrong when one partner opens the statements and the other feels audited. The hour starts with each partner naming one thing they are glad they spent on this year, then the facts: what came in, what went out, what surprised them. Only then does it turn to next year, one change each. Watch for the partner who brings a list of the other''s purchases; the glad box at the top is there to set a different tone.', '[{"id": "f0", "type": "textarea", "label": "Partner A: one thing I am glad we spent money on this year:"}, {"id": "f1", "type": "textarea", "label": "Partner B: one thing I am glad we spent money on this year:"}, {"id": "f2", "type": "textarea", "label": "The facts: roughly what came in, what went out, what surprised us:"}, {"id": "f3", "type": "textarea", "label": "Partner A: one change I would make next year, about my own spending:"}, {"id": "f4", "type": "textarea", "label": "Partner B: one change I would make next year, about my own spending:"}, {"id": "f5", "type": "textarea", "label": "What we will do together with this hour''s notes:"}]'::jsonb, array['couples', 'money', 'communication']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('sticky-note-feelings-thermometer-on-the-fridge-craft', 'Sticky Note Feelings Thermometer on the Fridge Craft', 'kids'::resource_kind, 'A paper thermometer taped to the fridge where a child moves a sticky note up or down to show how big their feelings are today.', 'Use it to give a child a daily way to show a feeling''s size before they have words for it.', array['Children']::text[], '20 minutes to make, then a glance a day', 'The child draws a tall thermometer on paper, colors it from cool at the bottom to hot at the top, and tapes it to the fridge. A sticky note with their name is the marker. Each day the parent asks where the note goes and says back what they see, without fixing or asking why. In session, look at a week of positions and ask the child what helped the note come down. Watch for the parent who moves the note for the child; the child''s hand is the point.', '[{"id": "f0", "type": "textarea", "label": "Draw your thermometer. What color is the cool bottom, and what color is the hot top?"}, {"id": "f1", "type": "textarea", "label": "Where is your note right now? What is making it that high or that low?"}, {"id": "f2", "type": "textarea", "label": "Draw or write what helps your note come down a little."}, {"id": "f3", "type": "textarea", "label": "What do you want your grown-up to say when your note is near the top?"}, {"id": "f4", "type": "textarea", "label": "Parent: one thing I noticed about where the note sat this week:"}]'::jsonb, array['children', 'emotion identification', 'craft']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('rolled-sock-snowball-toss-count-to-calm-play', 'Rolled Sock Snowball Toss Count to Calm Play', 'kids'::resource_kind, 'A living-room game where a child throws rolled-sock snowballs into a basket, counting each one slowly as a way to settle a big feeling.', 'Use it to give a child a physical way to burn off a surge and a count that slows the breath.', array['Children']::text[], 'Ten minutes', 'The parent and child roll ten pairs of socks into snowballs and set a laundry basket across the room. The child throws one at a time, saying the number out loud and taking one breath before the next. Misses are picked up and thrown again; the game ends when the basket holds ten. Then the child says how their body feels. Watch for the parent who turns it into a competition; the slow count is the skill, not the score.', '[{"id": "f0", "type": "textarea", "label": "Make your snowballs. How many can you roll?"}, {"id": "f1", "type": "textarea", "label": "Throw one, say the number, take a breath. What did your breath feel like by number five?"}, {"id": "f2", "type": "textarea", "label": "How did your body feel before the game, and how does it feel after?"}, {"id": "f3", "type": "textarea", "label": "When could you play sock snowballs next time a feeling gets big?"}, {"id": "f4", "type": "textarea", "label": "Parent: what I did while my child threw (count along, stay quiet, cheer):"}]'::jsonb, array['children', 'regulation', 'play']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('cereal-box-family-kind-notes-mailbox-build', 'Cereal Box Family Kind Notes Mailbox Build', 'kids'::resource_kind, 'A mailbox built from a cereal box where family members leave a kind note for each other, emptied together once a week.', 'Use it to give a family a daily, low-pressure way to put kind words into the house.', array['Children']::text[], '30 minutes to build, then one note a day', 'The child cuts a slot in a cereal box, covers it in paper and decorates it, and the family agrees on a spot for it. Every family member drops in one note a day, even a drawing, addressed to someone in the house. On a set evening the child plays mail carrier and delivers them. The parent writes a note too, every day, and reads theirs aloud. Watch for the week when one person gets no mail; the parent makes sure that does not happen twice.', '[{"id": "f0", "type": "textarea", "label": "Build your mailbox. What does it look like, and where will it live?"}, {"id": "f1", "type": "textarea", "label": "Write or draw one kind note for someone in your house."}, {"id": "f2", "type": "textarea", "label": "Who got a note from you this week, and what did it say?"}, {"id": "f3", "type": "textarea", "label": "What note did you get that you want to keep?"}, {"id": "f4", "type": "textarea", "label": "Parent: what I noticed when the notes were delivered:"}]'::jsonb, array['children', 'family', 'craft']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('mirror-fog-draw-then-wipe-away-the-worry-play', 'Mirror Fog Draw Then Wipe Away the Worry Play', 'kids'::resource_kind, 'A bathroom-mirror game after a warm bath where a child draws their worry in the fog and wipes it away with their hand.', 'Use it to give a child a bath-time way to put a worry down before bed.', array['Children']::text[], 'Five minutes after the bath', 'After a warm bath the mirror is fogged and ready. The child draws the worry with a finger, a shape or a face or a word, and tells the parent what it is. Then they take a big breath and wipe the mirror clear with their palm, and the parent names what is left: a clean mirror and the child''s face. Watch for the parent who hurries the drawing to get to the wiping; the telling is the part that matters.', '[{"id": "f0", "type": "textarea", "label": "Draw your worry in the fog. What does it look like?"}, {"id": "f1", "type": "textarea", "label": "Tell your grown-up what the worry is about, in your own words."}, {"id": "f2", "type": "textarea", "label": "Take a big breath and wipe it away. What do you see in the mirror now?"}, {"id": "f3", "type": "textarea", "label": "What do you want to think about instead before bed?"}, {"id": "f4", "type": "textarea", "label": "Parent: what my child drew, and what I said when the mirror was clear:"}]'::jsonb, array['children', 'worry', 'play']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('human-knot-untangle-group-game', 'Human Knot Untangle Group Game', 'game'::resource_kind, 'A group game where everyone grabs two hands across a circle and must untangle into a ring without letting go.', 'Use it to give a group a shared problem that needs talking, patience and a tolerance for being stuck.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes with debrief', 'Six to ten people stand in a tight circle, reach across, and take two different hands, none belonging to a neighbor. Without letting go, the group untangles by stepping over, ducking under and turning until they stand in a ring, possibly facing both ways. Rounds: first in silence, then talking allowed. The debrief asks who led, who waited, and what it was like to be stuck. Watch for the person who lets go to make it work; name it kindly as the shortcut we all reach for.', '[{"id": "f0", "type": "textarea", "label": "Round one, in silence: what did you do when the group got stuck?"}, {"id": "f1", "type": "textarea", "label": "Round two, talking allowed: what changed?"}, {"id": "f2", "type": "textarea", "label": "Who led, and how did the group decide to follow?"}, {"id": "f3", "type": "textarea", "label": "What it was like to be stuck in the middle with no obvious move:"}, {"id": "f4", "type": "textarea", "label": "Where in your week do you feel this stuck, and what would ''keep holding on'' look like there?"}]'::jsonb, array['game', 'group', 'problem solving']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('freeze-dance-name-a-feeling-when-the-music-stops-game', 'Freeze Dance Name a Feeling When the Music Stops Game', 'game'::resource_kind, 'A freeze-dance game where players hold a pose when the music stops and name the feeling the pose looks like.', 'Use it to get bodies moving and feeling words flowing in the same ten minutes.', array['Children', 'Groups']::text[], '15 minutes', 'Music plays and everyone dances. When it stops, players freeze in whatever shape they are in, and the leader points to one frozen player who names the feeling their pose looks like and says one thing that gives them that feeling. Then the music restarts. Every player gets pointed to at least once. Debrief asks which pose was easiest to name and which feeling nobody picked. Watch for the child who freezes small every time; point to them early and warmly.', '[{"id": "f0", "type": "textarea", "label": "The pose you froze in, and the feeling you said it looked like:"}, {"id": "f1", "type": "textarea", "label": "One thing that gives you that feeling:"}, {"id": "f2", "type": "textarea", "label": "A pose someone else made that you would have named differently:"}, {"id": "f3", "type": "textarea", "label": "A feeling nobody picked today:"}, {"id": "f4", "type": "textarea", "label": "What it was like to be pointed at and have everyone wait for your word:"}]'::jsonb, array['game', 'children', 'emotion identification']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('shoe-pile-find-the-owner-ask-a-question-game', 'Shoe Pile Find the Owner Ask a Question Game', 'game'::resource_kind, 'An icebreaker where everyone adds one shoe to a pile, draws someone else''s, finds the owner and asks them one question.', 'Use it to get a new group talking in pairs without anyone having to choose a partner.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Each player puts one shoe in the center. On go, everyone takes a shoe that is not theirs, finds its owner, and returns it with one question from the card deck: what did you have for breakfast, what song is stuck in your head, what are you looking forward to. Three rounds, new shoe each time. The debrief asks who they met and what stuck. Watch for the player who finds the owner and hands the shoe over in silence; the question is the game.', '[{"id": "f0", "type": "textarea", "label": "Round one: whose shoe did you draw, and what did you ask?"}, {"id": "f1", "type": "textarea", "label": "Round two: what answer surprised you?"}, {"id": "f2", "type": "textarea", "label": "Round three: a question you wished you had been asked:"}, {"id": "f3", "type": "textarea", "label": "Someone you had not spoken to before today, and one thing you now know about them:"}, {"id": "f4", "type": "textarea", "label": "What it was like to walk up to a stranger holding their shoe:"}]'::jsonb, array['game', 'group', 'social skills']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('three-favorite-things-category-clap-circle-game', 'Three Favorite Things Category Clap Circle Game', 'game'::resource_kind, 'A rhythm circle game where players clap a beat and name a favorite in the called category before the beat comes round again.', 'Use it to practice thinking under a little pressure and letting a miss be funny instead of fatal.', array['Groups', 'Teens', 'Children']::text[], '15 minutes', 'The circle claps a slow two-beat rhythm. The leader calls a category (favorite foods, favorite sounds, places that feel safe) and each player in turn says one answer on the beat. A miss or a repeat ends that round with a group cheer, and that player picks the next category. Speed up as the group warms up. The debrief asks what happened in the body when their turn was coming. Watch for the player who freezes and apologizes; the cheer is for the miss.', '[{"id": "f0", "type": "textarea", "label": "The category you found easiest, and the one that stumped you:"}, {"id": "f1", "type": "textarea", "label": "What happened in your body as your turn came around:"}, {"id": "f2", "type": "textarea", "label": "What it was like when you missed and the group cheered:"}, {"id": "f3", "type": "textarea", "label": "The category you called, and why you chose it:"}, {"id": "f4", "type": "textarea", "label": "Where else in your week does a beat come around before you are ready?"}]'::jsonb, array['game', 'group', 'attention']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('hospital-hallway-visit-steadiness-plan-sheet', 'Hospital Hallway Visit Steadiness Plan Sheet', 'worksheet'::resource_kind, 'A steadiness plan for visiting someone in the hospital when the smells, sounds and corridors stir up an old time.', 'Use it to help a client get to a bedside and back without the hallway taking them somewhere else.', array['Adults', 'Teens']::text[], '20 minutes before the visit', 'Hospitals carry a lot of clients straight back to a hard time, and the visit still matters to them. The sheet plans the approach: who comes along, the entrance and the route, what the client will hold or smell on the way in, the signal that means step outside, and how long the visit will be before it starts. Afterward it records what helped. Keep the sheet on the stabilizing side; the visit is the goal, not the memory. Watch for the client who plans to go alone to prove something.', '[{"id": "f0", "type": "textarea", "label": "Who I am visiting, and why it matters to me to go:"}, {"id": "f1", "type": "textarea", "label": "Who comes with me, and what they know about what hospitals do to me:"}, {"id": "f2", "type": "textarea", "label": "The route in, and what I will hold, smell or listen to on the way:"}, {"id": "f3", "type": "textarea", "label": "My signal for stepping outside, and where I will go:"}, {"id": "f4", "type": "textarea", "label": "How long the visit will be, decided now:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what helped most, for next time:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'pacing']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('nightmares-mean-i-am-going-backward-gentle-check-sheet', 'Nightmares Mean I Am Going Backward Gentle Check Sheet', 'cbt'::resource_kind, 'A gentle check sheet for the belief that a run of bad nights means all the progress has been lost.', 'Use it to put a hard week of sleep next to the wider record of how the client is doing.', array['Adults', 'Teens']::text[], '15 minutes in session', 'A few nights of nightmares often get read as proof that the work has unraveled. The sheet records the belief and how strongly it is held, then the evidence on both sides, including what has stayed steady in the daytime through the bad nights, and what tends to stir nights up (a date, the news, a hard conversation). The last box is a kinder sentence that still takes the nights seriously. Complete it in session rather than as homework; the nights themselves are not written out here.', '[{"id": "f0", "type": "textarea", "label": "The thought about the bad nights, in my words, and how much I believe it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "What has stayed steady in my days through these nights:"}, {"id": "f2", "type": "textarea", "label": "What tends to stir my nights up, as far as I can tell:"}, {"id": "f3", "type": "textarea", "label": "What I did to get through the mornings after:"}, {"id": "f4", "type": "textarea", "label": "A sentence about the week that is true and does not call it going backward:"}]'::jsonb, array['PTSD and trauma', 'sleep', 'core CBT']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('body-as-a-guard-dog-that-can-learn-to-lie-down-page', 'Body as a Guard Dog That Can Learn to Lie Down Page', 'act'::resource_kind, 'An acceptance page that pictures the startled, watchful body as a loyal guard dog that is doing its job and can learn a new command.', 'Use it to help a client treat their alarm system with respect while practicing settling it.', array['Adults', 'Teens']::text[], '20 minutes in session, then a line a day', 'A body that jumps at every sound is often hated by the person living in it. The page reframes it as a guard dog that learned to bark for good reasons and can learn to lie down when told. The client names what the dog barks at, how they usually speak to it, and a calmer command they could try: a hand on the chest, a slow exhale, a sentence. It records one moment the dog lay down. Watch for the client who wants the dog gone; the aim is a dog that rests, not one that leaves.', '[{"id": "f0", "type": "textarea", "label": "What my guard dog barks at most these days:"}, {"id": "f1", "type": "textarea", "label": "How I usually talk to it when it barks (angry, ashamed, pleading):"}, {"id": "f2", "type": "textarea", "label": "The command I will try instead (a touch, a breath, a sentence):"}, {"id": "f3", "type": "textarea", "label": "One moment this week when the dog settled, even a little:"}, {"id": "f4", "type": "textarea", "label": "What the dog has protected me from that I can thank it for:"}]'::jsonb, array['PTSD and trauma', 'acceptance', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-a-familiar-song-through-one-earbud-card', 'Self-Soothe With a Familiar Song Through One Earbud Card', 'dbt'::resource_kind, 'A Self-Soothe card for a crowded or loud place, using one earbud and a song the client knows by heart as an anchor.', 'Use it to give a client a portable soothing skill that keeps one ear on the room.', array['Adults', 'Teens']::text[], 'One song, whenever needed', 'A song known by heart gives the mind somewhere to stand while the body settles. The card asks the client to choose two songs in advance that have never been tied to a hard time, keep one earbud in so the room stays audible, and give the song full attention: the first line, the instrument they follow, the breath that matches it. It records where the skill was used and the distress before and after. Watch for the client who picks a song that pulls them back; the choosing is done in session for that reason.', '[{"id": "f0", "type": "textarea", "label": "The two songs I will keep ready, and why they feel safe:"}, {"id": "f1", "type": "textarea", "label": "Where I used the skill, and what was going on around me:"}, {"id": "f2", "type": "textarea", "label": "My distress before (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What I followed in the song (a voice, a drum, a line):"}, {"id": "f4", "type": "textarea", "label": "My distress after (0 to 10), and how my body felt by the last note:"}]'::jsonb, array['PTSD and trauma', 'self-soothing', 'distress tolerance']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('nightmare-wake-up-signal-and-light-plan-for-partners', 'Nightmare Wake-Up Signal and Light Plan for Partners', 'couples'::resource_kind, 'A plan for partners for the night one wakes from a nightmare: what the other says, where the light is, and what not to do.', 'Use it to give a couple an agreed response to a hard night, decided in daylight.', array['Couples']::text[], '20 minutes in session', 'Partners often guess in the dark: hold them, do not touch them, turn on the light, stay still. The plan is written in daylight by both. The partner who wakes says what helps and what makes it worse, in plain terms, without describing the dreams. The other partner says what they can do and what they need afterward. They agree on a lamp, a phrase, and a morning check-in. Keep it to the stabilizing side. Watch for the supporting partner who takes the night personally; a line for their feelings belongs on the sheet.', '[{"id": "f0", "type": "textarea", "label": "Partner who wakes: what helps in the first minute (words, light, space, touch or no touch):"}, {"id": "f1", "type": "textarea", "label": "Partner who wakes: what makes it worse, so my partner knows:"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: what I can do, and what I need afterward:"}, {"id": "f3", "type": "textarea", "label": "Our phrase, our lamp, and where it sits:"}, {"id": "f4", "type": "textarea", "label": "How we check in the next morning, in one or two sentences:"}]'::jsonb, array['PTSD and trauma', 'couples', 'safety']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('winter-storm-forecast-worry-versus-prep-split-sheet', 'Winter Storm Forecast Worry Versus Prep Split Sheet', 'worksheet'::resource_kind, 'A split sheet for the days before a forecast storm, separating useful preparation from the worry that keeps checking the radar.', 'Use it to help a client do the useful things once and notice when checking has taken over.', array['Adults', 'Teens']::text[], '15 minutes when the forecast comes out', 'A storm forecast gives worry a target for three days. The sheet lists the preparations that actually help, each done once and checked off, and then the checking behaviors that feel like preparing but are not: the radar refreshes, the news loops, the repeated asks for reassurance. A tally keeps count of the checks. Watch for the client who adds more prep to the list every hour; the list is closed once it is written.', '[{"id": "f0", "type": "textarea", "label": "The storm, and when it is expected:"}, {"id": "f1", "type": "textarea", "label": "Preparations that actually help, each done once (supplies, plans, charging):"}, {"id": "f2", "type": "textarea", "label": "What I keep doing that feels like preparing but is checking:"}, {"id": "f3", "type": "textarea", "label": "My rule for how often I will look at the forecast:"}, {"id": "f4", "type": "textarea", "label": "Tally of checks today, honestly:"}, {"id": "f5", "type": "textarea", "label": "After the storm: what the worry got right, and what it did not:"}]'::jsonb, array['anxiety', 'worry', 'uncertainty']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('if-the-doctor-s-office-calls-back-it-must-be-bad-news-sheet', 'If the Doctor''s Office Calls Back It Must Be Bad News Sheet', 'cbt'::resource_kind, 'A probability sheet for the callback from a doctor''s office that the mind has already decided is bad.', 'Use it to help a client put real odds beside the certainty their anxiety is offering.', array['Adults']::text[], '15 minutes', 'A missed call from a medical office becomes a sentence within seconds. The sheet records the prediction and how sure the client is, then lists every reason an office calls (scheduling, billing, a routine result, a question, a reminder) and the client''s own history of callbacks and what they were. The last box records the actual call. Watch for the client who will not call back until they feel ready; the delay is where the anxiety feeds.', '[{"id": "f0", "type": "textarea", "label": "The missed call, and what my mind decided it meant:"}, {"id": "f1", "type": "textarea", "label": "How sure I am (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Every reason a medical office calls someone back:"}, {"id": "f3", "type": "textarea", "label": "The last few callbacks I got, and what they actually were:"}, {"id": "f4", "type": "textarea", "label": "When I will call back, and what I will do in the minutes before:"}, {"id": "f5", "type": "textarea", "label": "What the call actually was:"}]'::jsonb, array['anxiety', 'predictions', 'core CBT']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('worry-as-a-browser-with-fifty-open-tabs-page', 'Worry as a Browser With Fifty Open Tabs Page', 'act'::resource_kind, 'A defusion page that pictures an anxious mind as a browser with fifty tabs open, each one playing its own sound.', 'Use it to help a client notice the tabs without needing to read every one before closing the laptop.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'A worried mind feels like it has to finish every tab before it can rest. The page asks the client to list their open tabs as tab titles, pick the one playing the loudest sound, and practice noticing it as a tab, not a task. It then asks what the client wants to do with the next hour and whether the tabs can stay open while they do it. Watch for the client who tries to close every tab first; the page is about working with tabs open.', '[{"id": "f0", "type": "textarea", "label": "My open tabs right now, as short tab titles:"}, {"id": "f1", "type": "textarea", "label": "The one playing the loudest sound:"}, {"id": "f2", "type": "textarea", "label": "What that tab wants me to do before I can rest:"}, {"id": "f3", "type": "textarea", "label": "What I actually want the next hour to hold:"}, {"id": "f4", "type": "textarea", "label": "What it was like to leave the tabs open and do it anyway:"}]'::jsonb, array['anxiety', 'defusion', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-the-performance-review-meeting-card', 'Cope Ahead for the Performance Review Meeting Card', 'dbt'::resource_kind, 'A Cope Ahead card for the annual review meeting, rehearsed in imagery with the hardest moment included.', 'Use it to help a client walk into a review having already practiced the sentence that scares them most.', array['Adults']::text[], '20 minutes, a few days before the review', 'A review meeting is a sitting-still situation where anxiety has nowhere to go. The card describes the meeting in detail, names the emotion most likely to show up and the moment most likely to bring it, and chooses the skills for that moment: paced breathing under the table, a prepared question, a sentence for feedback that stings. The client then rehearses it in imagery, including the hard moment going as badly as feared, and coping anyway. Watch for the client who only rehearses the good version.', '[{"id": "f0", "type": "textarea", "label": "The meeting: where, who, how long, what will be covered:"}, {"id": "f1", "type": "textarea", "label": "The moment most likely to spike me, and the emotion it brings:"}, {"id": "f2", "type": "textarea", "label": "The skills I will use in that moment, in order:"}, {"id": "f3", "type": "textarea", "label": "The sentence I will say if the feedback stings:"}, {"id": "f4", "type": "textarea", "label": "What I noticed rehearsing the hard version in imagery:"}, {"id": "f5", "type": "textarea", "label": "How I will take care of myself after the meeting ends:"}]'::jsonb, array['anxiety', 'cope ahead', 'emotion regulation']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('unload-one-shelf-of-the-dishwasher-micro-step-sheet', 'Unload One Shelf of the Dishwasher Micro Step Sheet', 'worksheet'::resource_kind, 'A micro-step sheet that sets the day''s whole task as one shelf of the dishwasher, finished and written down.', 'Use it to give a client a task small enough to complete on a heavy day and a record that they did.', array['Adults', 'Teens']::text[], 'Five minutes a day for one week', 'On a heavy day the clean dishwasher is as impossible as the dirty kitchen. The sheet sets the task as one shelf, the top rack only, and asks the client to record the time it took, the mood before and after, and whether they stopped at one shelf or kept going. Keeping going is allowed but not required. Watch for the client who does the whole kitchen on day one and nothing after; the sheet is about the smallest repeatable thing.', '[{"id": "f0", "type": "textarea", "label": "Which shelf I will do today, and roughly when:"}, {"id": "f1", "type": "textarea", "label": "My mood before (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "How long it actually took:"}, {"id": "f3", "type": "textarea", "label": "Whether I stopped at one shelf or kept going, and either is fine:"}, {"id": "f4", "type": "textarea", "label": "My mood after (0 to 10):"}, {"id": "f5", "type": "textarea", "label": "What my mind said about such a small task, and what I say back:"}]'::jsonb, array['depression', 'behavioral activation', 'routines']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('resting-saturday-means-i-wasted-the-weekend-thought-record', 'Resting Saturday Means I Wasted the Weekend Thought Record', 'cbt'::resource_kind, 'A thought record for the Saturday spent resting that becomes, by Sunday night, a wasted weekend and a verdict on the person.', 'Use it to separate what the client needed from what the rule about weekends says they should have done.', array['Adults']::text[], '15 minutes on Sunday evening', 'Rest reads as waste to a client whose mood is low and whose rules are strict. The record writes the Saturday as it was, the thought about it, the emotion and its strength, and the evidence: what the week before cost, what rest actually did for the body, what a friend would call the same Saturday. The balanced thought is written in the client''s words. Watch for the client who agrees in session and reopens the case Sunday night; a copy of the balanced thought goes on the phone.', '[{"id": "f0", "type": "textarea", "label": "What I actually did on Saturday, hour by hour, without judgment:"}, {"id": "f1", "type": "textarea", "label": "The thought about it, word for word, and how much I believe it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The emotion, and how strong:"}, {"id": "f3", "type": "textarea", "label": "What the week before had cost me, and what rest did:"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend who spent Saturday the same way:"}, {"id": "f5", "type": "textarea", "label": "A more balanced thought, in my own words:"}]'::jsonb, array['depression', 'thought record', 'rest']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('low-mood-as-a-heavy-backpack-i-can-still-walk-with-page', 'Low Mood as a Heavy Backpack I Can Still Walk With Page', 'act'::resource_kind, 'An acceptance page that pictures low mood as a heavy backpack: real weight, slower steps, and still a direction to walk in.', 'Use it to help a client carry a mood while taking a small step toward what matters.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'Waiting for the backpack to come off before moving means not moving for a long time. The page asks the client to describe the weight honestly, name where they would walk if the pack were lighter, and pick one short distance to walk with it on today. It records what the walk was like with the weight still there. Watch for the client who takes this as pressure to carry more; the page is about direction at any pace, and the pack is allowed to be heavy.', '[{"id": "f0", "type": "textarea", "label": "How heavy the pack is today, in my own words:"}, {"id": "f1", "type": "textarea", "label": "Where I would walk if it were lighter:"}, {"id": "f2", "type": "textarea", "label": "One short distance I can walk today with the pack on:"}, {"id": "f3", "type": "textarea", "label": "What the walk was actually like with the weight still there:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the pack when I am moving versus sitting with it:"}]'::jsonb, array['depression', 'acceptance', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-leaving-the-curtains-closed-card', 'Opposite Action to Leaving the Curtains Closed Card', 'dbt'::resource_kind, 'An Opposite Action card for the morning the curtains stay shut and the room stays dim because the mood says why bother.', 'Use it to give a client one physical opposite action that changes the room before it changes the mood.', array['Adults', 'Teens']::text[], 'Two minutes each morning for a week', 'Closed curtains at noon are both a sign of the mood and a way of feeding it. The card names the emotion and its urge to keep the room dim, checks whether staying shut fits the facts of the day, and plans the opposite all the way: curtains open, window cracked, face turned to the light for one minute. It logs the mood after a week of mornings. Watch for the client who opens the curtains and goes back to bed; the one minute at the window is part of the action.', '[{"id": "f0", "type": "textarea", "label": "The emotion in the morning, and what it tells me to do with the room:"}, {"id": "f1", "type": "textarea", "label": "Does keeping the room dark fit the facts of today? What does it cost?"}, {"id": "f2", "type": "textarea", "label": "The opposite action, all the way (curtains, window, one minute facing the light):"}, {"id": "f3", "type": "textarea", "label": "Each morning this week: done or not, and mood after (0 to 10):"}, {"id": "f4", "type": "textarea", "label": "What changed, even slightly, by the end of the week:"}]'::jsonb, array['depression', 'opposite action', 'routines']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('saying-good-morning-through-a-low-spell-ritual-for-partners', 'Saying Good Morning Through a Low Spell Ritual for Partners', 'couples'::resource_kind, 'A small morning ritual for partners when one is in a low spell: a greeting, one question, and no fixing before coffee.', 'Use it to keep a couple connected each morning through a stretch when one partner has little to give.', array['Couples']::text[], 'Two minutes each morning for two weeks', 'A low spell makes mornings silent, and silence is read by the other partner as distance. The ritual is small on purpose: the low partner says good morning and one true word about how they are; the other says good morning, one question that can be answered in a word, and nothing about what should be done. Both write what it was like after two weeks. Watch for the supporting partner who turns the question into a check-up; one word is the whole answer.', '[{"id": "f0", "type": "textarea", "label": "Partner in the low spell: the one true word I can offer most mornings:"}, {"id": "f1", "type": "textarea", "label": "Supporting partner: the question I will ask that can be answered in a word:"}, {"id": "f2", "type": "textarea", "label": "What we will not do before coffee (fix, plan, review):"}, {"id": "f3", "type": "textarea", "label": "Partner in the low spell, after two weeks: what the ritual was like:"}, {"id": "f4", "type": "textarea", "label": "Supporting partner, after two weeks: what the ritual was like:"}]'::jsonb, array['depression', 'couples', 'connection']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('winter-coat-gloves-and-keys-launch-pad-by-the-door-sheet', 'Winter Coat Gloves and Keys Launch Pad by the Door Sheet', 'worksheet'::resource_kind, 'A setup sheet for one spot by the door where the coat, gloves, keys, badge and bag live, so leaving the house stops being a search.', 'Use it to help a client build the one place that makes mornings leave on time.', array['Adults', 'Teens']::text[], '30 minutes to set up, then one week', 'Winter adds four more things to find before the door, and every one is a chance to lose ten minutes. The sheet lists everything that must leave with the client, chooses one spot by the door (a hook, a tray, a basket), and writes the rule for the evening before: everything lands there as the client walks in. A week of yes or no tracks the habit. Watch for the client who builds a beautiful launch pad and then drops the keys on the counter anyway; the walk-in rule is the practice.', '[{"id": "f0", "type": "textarea", "label": "Everything that has to leave the house with me on a weekday:"}, {"id": "f1", "type": "textarea", "label": "The one spot by the door, and what goes on or in it:"}, {"id": "f2", "type": "textarea", "label": "The rule for walking in at night, in one sentence:"}, {"id": "f3", "type": "textarea", "label": "Each day this week: did everything land on the pad? (yes or no):"}, {"id": "f4", "type": "textarea", "label": "The thing that still went missing, and where it was:"}, {"id": "f5", "type": "textarea", "label": "What I will adjust about the pad:"}]'::jsonb, array['ADHD', 'routines', 'executive function']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('mind-as-a-browser-autoplaying-the-next-video-page', 'Mind as a Browser Autoplaying the Next Video Page', 'act'::resource_kind, 'A defusion page that pictures the attention-hungry mind as a browser that queues the next video before the current one ends.', 'Use it to help a client notice the autoplay moment and choose whether to let it run.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'The mind queues the next thing before this one is done, and the client arrives at the end of an evening unsure what they watched. The page names the autoplay moments in a day, what they feel like from the inside, and the single question the client can ask when the countdown starts: is this what I want next? It records one moment they let it run and one they chose. Watch for the client who wants to disable autoplay for good; noticing is the skill.', '[{"id": "f0", "type": "textarea", "label": "Where autoplay kicks in during my day (screens, tasks, conversations):"}, {"id": "f1", "type": "textarea", "label": "What the autoplay moment feels like from the inside:"}, {"id": "f2", "type": "textarea", "label": "The question I will ask when the countdown starts:"}, {"id": "f3", "type": "textarea", "label": "One moment this week I let it run, and what that was like:"}, {"id": "f4", "type": "textarea", "label": "One moment I chose the next thing on purpose, and what that was like:"}]'::jsonb, array['ADHD', 'defusion', 'attention']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('wise-mind-at-the-checkout-impulse-rack-card', 'Wise Mind at the Checkout Impulse Rack Card', 'dbt'::resource_kind, 'A Wise Mind card for the thirty seconds in the checkout line when the impulse rack is doing its job.', 'Use it to give a client a short pause between the grab and the belt.', array['Adults', 'Teens']::text[], 'Thirty seconds, at every checkout for a week', 'The impulse rack is built for a mind that moves fast. The card asks the client to notice what emotion mind wants (the gum, the gadget, the magazine), what reasonable mind says about the budget, and then to breathe once and ask wise mind what fits. It logs each checkout for a week: grabbed, put back, or never picked up. Watch for the client who scores themselves on the outcome; the pause counts whether or not the item goes on the belt.', '[{"id": "f0", "type": "textarea", "label": "What emotion mind reaches for at the rack:"}, {"id": "f1", "type": "textarea", "label": "What reasonable mind says about it:"}, {"id": "f2", "type": "textarea", "label": "The one-breath question I will ask wise mind:"}, {"id": "f3", "type": "textarea", "label": "Each checkout this week: grabbed, put back, or never picked up:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the pause by the end of the week:"}]'::jsonb, array['ADHD', 'wise mind', 'impulsivity']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('rhyming-backpack-check-song-before-the-door-play', 'Rhyming Backpack Check Song Before the Door Play', 'kids'::resource_kind, 'A made-up rhyming song a child sings at the door that names every item in the backpack, with a parent clapping the beat.', 'Use it to give a child a routine that remembers the list so they do not have to.', array['Children']::text[], 'Two minutes each school morning', 'A list on the wall is easy to walk past; a song is harder to skip. The child and parent write a short rhyming song in session or at home that names each item (folder, lunch, water, library book) and ends with a zip and a high five. The parent claps the beat and does not say the words; the child sings and checks. In session, the child performs it and says which line gets forgotten most. Watch for the parent who sings it for the child on busy mornings.', '[{"id": "f0", "type": "textarea", "label": "Write your backpack song. What things go in it?"}, {"id": "f1", "type": "textarea", "label": "What is the last line, right before the zip?"}, {"id": "f2", "type": "textarea", "label": "Which thing do you forget most? Give it the loudest line."}, {"id": "f3", "type": "textarea", "label": "Sing it at the door for a week. Which mornings did you remember everything?"}, {"id": "f4", "type": "textarea", "label": "Parent: what I did while my child sang (clapped, waited, stayed quiet):"}]'::jsonb, array['ADHD', 'children', 'routines']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('old-pain-pills-in-the-cabinet-disposal-plan-sheet', 'Old Pain Pills in the Cabinet Disposal Plan Sheet', 'worksheet'::resource_kind, 'A plan for the leftover pain pills in the medicine cabinet that keep showing up in the client''s thoughts during hard weeks.', 'Use it to help a client decide what happens to the pills and who helps, before the next hard week.', array['Adults']::text[], '20 minutes, then one trip', 'Leftover pills from an old injury or surgery sit quietly until an urge gives them a voice. The sheet names what is in the house, where, and how often the client''s mind visits it. It then plans the disposal: a pharmacy take-back, a drop box, a trusted person who handles it, and the date. The last box is what the client will do the first time the mind looks for them and finds them gone. Watch for the client who wants to keep a few just in case; that is the conversation to have in session.', '[{"id": "f0", "type": "textarea", "label": "What is in the house, and where:"}, {"id": "f1", "type": "textarea", "label": "How often my mind goes there, and in what kind of week:"}, {"id": "f2", "type": "textarea", "label": "Where and how I will dispose of them (take-back, drop box, a trusted person):"}, {"id": "f3", "type": "textarea", "label": "Who helps, and the date it will be done:"}, {"id": "f4", "type": "textarea", "label": "What I will do the first time an urge looks for them and finds them gone:"}]'::jsonb, array['addiction', 'substance use', 'safety']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('one-slip-means-the-whole-effort-is-gone-all-or-nothing-sheet', 'One Slip Means the Whole Effort Is Gone All-or-Nothing Sheet', 'cbt'::resource_kind, 'An all-or-nothing sheet for the night after a slip in substance use, when the mind says the whole run of weeks is erased.', 'Use it to help a client count what a slip actually undid and what it did not.', array['Adults', 'Teens']::text[], '15 minutes, within a day of the slip', 'The thought after a slip is often more dangerous than the slip: it is all gone, so it does not matter now. The sheet records what happened in plain facts, the all-or-nothing sentence, and then what the weeks before actually built: habits, people, mornings, money, trust. It asks what the next twenty-four hours look like if the weeks still count. Watch for the client who uses the sheet to minimize; the facts box is for the real amount and the real context.', '[{"id": "f0", "type": "textarea", "label": "What happened, in facts (what, how much, where, with whom):"}, {"id": "f1", "type": "textarea", "label": "The sentence my mind said afterward, and how much I believe it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What the weeks before built that is still here this morning:"}, {"id": "f3", "type": "textarea", "label": "What the slip actually cost, named honestly:"}, {"id": "f4", "type": "textarea", "label": "What the next twenty-four hours look like if the weeks still count:"}, {"id": "f5", "type": "textarea", "label": "Who I will tell, and when:"}]'::jsonb, array['addiction', 'urges', 'all-or-nothing']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('urge-as-a-street-vendor-shouting-at-every-passerby-page', 'Urge as a Street Vendor Shouting at Every Passerby Page', 'act'::resource_kind, 'A defusion page that pictures an urge as a street vendor calling out to everyone who walks past, including the client.', 'Use it to help a client hear the pitch without stopping at the cart.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'A vendor''s call is loud, personal and aimed at nobody in particular. The page asks the client to write down the urge''s exact pitch, the times of day it shouts loudest, and what the client usually does when it starts. Then it practices walking past: hearing the words, keeping the pace, noticing the call fade behind them. It records one walk-past this week. Watch for the client who argues with the vendor; arguing is stopping at the cart.', '[{"id": "f0", "type": "textarea", "label": "The urge''s pitch, in the words it actually uses:"}, {"id": "f1", "type": "textarea", "label": "When and where it shouts loudest:"}, {"id": "f2", "type": "textarea", "label": "What I usually do when it starts:"}, {"id": "f3", "type": "textarea", "label": "One time this week I kept walking, and what the call did behind me:"}, {"id": "f4", "type": "textarea", "label": "Where I was headed that mattered more than the cart:"}]'::jsonb, array['addiction', 'urges', 'defusion']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('holiday-party-leave-signal-and-ride-home-plan-for-partners', 'Holiday Party Leave Signal and Ride Home Plan for Partners', 'couples'::resource_kind, 'A plan for partners heading to a party where alcohol is everywhere: the leave signal, the ride, and who holds the keys.', 'Use it to let a couple walk into a party with the exit already agreed.', array['Couples']::text[], '15 minutes before the party', 'A party is easier to leave when the leaving was planned by both. The partner working on substance use says what will make the night hard and the signal they will use when it is time to go. The other partner says what they will do when they see it, how they will handle their own drinking that night, and who drives. Both agree on the latest they will stay. Watch for the supporting partner who agrees to stay sober and then has one; a line about their own plan is on the sheet.', '[{"id": "f0", "type": "textarea", "label": "Partner working on substance use: what will make this night hard for me:"}, {"id": "f1", "type": "textarea", "label": "My leave signal, and what I need my partner to do when they see it:"}, {"id": "f2", "type": "textarea", "label": "Supporting partner: my own plan for drinking tonight, and who drives:"}, {"id": "f3", "type": "textarea", "label": "The latest we will stay, decided now:"}, {"id": "f4", "type": "textarea", "label": "What we will do together when we get home:"}]'::jsonb, array['addiction', 'couples', 'planning']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('being-put-on-hold-for-the-third-time-anger-log-sheet', 'Being Put on Hold for the Third Time Anger Log Sheet', 'worksheet'::resource_kind, 'An anger log for the customer service call that transfers, holds and transfers again, tracking the heat and what the client does with it.', 'Use it to help a client watch anger build on a call and choose the moment to step back.', array['Adults']::text[], 'During one call, then 10 minutes after', 'Hold music is a slow build with no outlet, and the person who finally answers gets the whole pile. The log tracks the anger reading at each transfer, the sentence the client wants to say, and what they can do during the hold (stand up, breathe, write the goal of the call at the top). The last box records how they spoke to the last agent. Watch for the client who logs the anger and is proud of the outburst; the goal line is what the call was for.', '[{"id": "f0", "type": "textarea", "label": "What the call is for, written at the top before I dial:"}, {"id": "f1", "type": "textarea", "label": "Anger reading at the first hold (0 to 10), and the sentence in my head:"}, {"id": "f2", "type": "textarea", "label": "Anger reading at the second and third hold, and what I did while waiting:"}, {"id": "f3", "type": "textarea", "label": "What I wanted to say to the person who finally answered:"}, {"id": "f4", "type": "textarea", "label": "What I actually said, and how the call ended:"}, {"id": "f5", "type": "textarea", "label": "What I will do during the hold next time:"}]'::jsonb, array['anger management', 'self-monitoring', 'de-escalation']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('they-left-the-dishes-so-they-expect-me-to-do-them-sheet', 'They Left the Dishes So They Expect Me to Do Them Sheet', 'cbt'::resource_kind, 'A mind-reading sheet for the sink full of someone else''s dishes and the intention the client has read into them.', 'Use it to help a client separate the dishes from the story about what they mean.', array['Adults', 'Teens']::text[], '10 minutes at the sink', 'The dishes are a fact; the expectation is a story, and the anger belongs to the story. The sheet records the scene, the mind-read, how sure the client is, and the other reasons dishes get left: ran out of time, planned to do them after, did not notice, forgot. It then writes the plain request the client could make instead of the silent rage-wash. Watch for the client whose other reasons are all insults; offer one that is boring.', '[{"id": "f0", "type": "textarea", "label": "What I saw, in facts (what was in the sink, whose, how long):"}, {"id": "f1", "type": "textarea", "label": "What I decided it meant about what they expect of me:"}, {"id": "f2", "type": "textarea", "label": "How sure I am (0 to 100), and how angry (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "Boring reasons someone leaves dishes:"}, {"id": "f4", "type": "textarea", "label": "The plain request I could make instead:"}, {"id": "f5", "type": "textarea", "label": "How angry I am after writing it down (0 to 10):"}]'::jsonb, array['anger management', 'mind reading', 'communication']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('anger-as-a-smoke-alarm-over-burned-toast-page', 'Anger as a Smoke Alarm Over Burned Toast Page', 'act'::resource_kind, 'A defusion page that pictures anger as a smoke alarm that shrieks the same for burned toast as for a house fire.', 'Use it to help a client hear the alarm, check for the fire, and choose the response that fits.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'The alarm is not wrong to go off; it just cannot tell toast from a fire. The page asks the client to list this week''s alarms, sort them into toast and fire, and notice how the body responded the same to both. Then it asks what a toast response looks like: open a window, wave a towel, say one plain sentence. It records one alarm handled as toast. Watch for the client who wants the alarm removed; the aim is to check the kitchen before calling the fire department.', '[{"id": "f0", "type": "textarea", "label": "This week''s alarms, listed in a few words each:"}, {"id": "f1", "type": "textarea", "label": "Which were toast, and which were fire:"}, {"id": "f2", "type": "textarea", "label": "How my body responded to the toast ones:"}, {"id": "f3", "type": "textarea", "label": "What a toast response looks like for me (a window, a towel, one sentence):"}, {"id": "f4", "type": "textarea", "label": "One alarm this week I handled as toast, and what happened:"}]'::jsonb, array['anger management', 'defusion', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('willing-hands-while-reading-the-rude-review-card', 'Willing Hands While Reading the Rude Review Card', 'dbt'::resource_kind, 'A Willing Hands card for reading a harsh review or comment about the client''s work without the body clenching for a fight.', 'Use it to give a client a posture that changes the reading before the reply.', array['Adults']::text[], 'Five minutes, before and after reading', 'A rude comment about one''s work lands in the hands first: fists, a grip on the phone, fingers already typing. The card asks the client to turn the palms up, loosen the fingers, drop the shoulders, and read the comment once in that posture, then once more. It records the urge before and after and the reply, if any, written an hour later. Watch for the client who does willing hands and then types the reply with clenched teeth; the hour is part of the skill.', '[{"id": "f0", "type": "textarea", "label": "The comment, in a few words, and my first urge (0 to 10):"}, {"id": "f1", "type": "textarea", "label": "What my hands and shoulders were doing before I noticed:"}, {"id": "f2", "type": "textarea", "label": "Reading it with willing hands: what changed in the body:"}, {"id": "f3", "type": "textarea", "label": "The urge after the second read (0 to 10):"}, {"id": "f4", "type": "textarea", "label": "The reply I wrote an hour later, or the decision not to:"}]'::jsonb, array['anger management', 'willing hands', 'distress tolerance']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('balloon-blow-up-and-let-it-hiss-out-anger-game', 'Balloon Blow Up and Let It Hiss Out Anger Game', 'game'::resource_kind, 'A group game where players blow their week''s anger into a balloon, one breath per grievance, then let it hiss out slowly instead of popping.', 'Use it to show a group the difference between releasing anger slowly and letting it burst.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'Each player gets a balloon. In turn, they name one thing that made them angry this week and blow one breath into the balloon for it, until the balloon is full or they run out. Then, on the leader''s count, everyone pinches the neck and lets the air out slowly, making the longest hiss they can; the longest hiss wins the round. A pop is a lesson, not a loss. The debrief asks which felt better in the body and what a slow hiss looks like at home. Watch for the player who pops it on purpose for the laugh; ask what that costs.', '[{"id": "f0", "type": "textarea", "label": "The things you blew into your balloon this week:"}, {"id": "f1", "type": "textarea", "label": "How your body felt when the balloon was full:"}, {"id": "f2", "type": "textarea", "label": "How long your hiss lasted, and how your body felt when it was done:"}, {"id": "f3", "type": "textarea", "label": "What a slow hiss looks like for you at home, in real life:"}, {"id": "f4", "type": "textarea", "label": "What happens to the people near you when your balloon pops instead?"}]'::jsonb, array['anger management', 'game', 'regulation']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('not-confessing-the-thought-means-i-am-hiding-something-sheet', 'Not Confessing the Thought Means I Am Hiding Something Sheet', 'cbt'::resource_kind, 'A belief check sheet for the urge to confess every intrusive thought to a partner or friend so it does not count as hiding.', 'Use it to help a client test the belief that an unspoken thought is a secret with a cost.', array['Adults', 'Teens']::text[], '15 minutes in session', 'Confessing is a compulsion that feels like honesty. The sheet records the belief, how strongly it is held, and the evidence: what has happened the times the client did not confess, what the confessions did for the other person, and the difference between a thought and an act. The last box is one thought the client will let go unspoken this week and what they predict. Watch for the client who confesses the plan not to confess; name it kindly.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words, and how much I believe it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "What has actually happened the times I did not confess a thought:"}, {"id": "f2", "type": "textarea", "label": "What my confessions do for the person I confess to:"}, {"id": "f3", "type": "textarea", "label": "The difference between having a thought and doing a thing, in my words:"}, {"id": "f4", "type": "textarea", "label": "One thought I will leave unspoken this week, and what I predict will happen:"}, {"id": "f5", "type": "textarea", "label": "What actually happened:"}]'::jsonb, array['OCD', 'intrusive thoughts', 'core CBT']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('doubt-as-a-door-to-door-salesman-i-do-not-invite-in-page', 'Doubt as a Door-to-Door Salesman I Do Not Invite In Page', 'act'::resource_kind, 'A defusion page that treats obsessive doubt as a salesman at the door with a pitch that never changes.', 'Use it to help a client hear the pitch through the door and leave it closed.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'The salesman always has the same offer: certainty, if the client just does one more check. The page writes the pitch in his words, the times he rings, and what inviting him in has cost so far. Then it practices the closed door: noticing the knock, naming it, and going back to what the client was doing. It records one knock left unanswered. Watch for the client who opens the door to argue; the argument is the sale.', '[{"id": "f0", "type": "textarea", "label": "The salesman''s pitch, in the words he uses:"}, {"id": "f1", "type": "textarea", "label": "When he rings most, and what I am usually doing:"}, {"id": "f2", "type": "textarea", "label": "What letting him in has cost me so far:"}, {"id": "f3", "type": "textarea", "label": "What I will do when I hear the knock (notice, name, return):"}, {"id": "f4", "type": "textarea", "label": "One knock this week I left unanswered, and what happened next:"}]'::jsonb, array['OCD', 'defusion', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('observe-the-sticky-feeling-on-the-hands-without-washing-card', 'Observe the Sticky Feeling on the Hands Without Washing Card', 'dbt'::resource_kind, 'An Observe and Describe card for the feeling of something on the hands, noticed in words for two minutes before any decision about the sink.', 'Use it to give a client a mindful pause between the sticky feeling and the wash.', array['Adults', 'Teens']::text[], 'Two minutes, several times a day', 'The feeling arrives and the hands are at the sink before the mind has caught up. The card asks the client to stop, observe the sensation in detail (where exactly, what texture, how strong), describe it in plain words without the word dirty or dangerous, and watch it for two minutes. Only then is the decision about washing made, and logged. Watch for the client who describes it and washes at full strength; the two minutes count regardless of what follows.', '[{"id": "f0", "type": "textarea", "label": "Where on my hands the feeling is, exactly:"}, {"id": "f1", "type": "textarea", "label": "The sensation in plain words (texture, temperature, strength 0 to 10):"}, {"id": "f2", "type": "textarea", "label": "What my mind wants to add to the description, and what I leave out:"}, {"id": "f3", "type": "textarea", "label": "What the feeling did over two minutes:"}, {"id": "f4", "type": "textarea", "label": "What I decided about the sink, and why:"}]'::jsonb, array['OCD', 'mindfulness', 'core DBT']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('highway-lane-between-exits-surge-plan-sheet', 'Highway Lane Between Exits Surge Plan Sheet', 'worksheet'::resource_kind, 'A plan for a panic surge on the highway between two exits, where pulling over is not simple and the body wants out.', 'Use it to give a client a step list for the stretch of road that scares them most.', array['Adults']::text[], '20 minutes in session, then one drive', 'The highway stretch with no exit is the place panic likes best: the body says stop and the road says keep going. The sheet writes the steps before the drive: slow the car to the right lane, name the next exit aloud, one long exhale per mile marker, hands loose on the wheel, the radio on something known. It records the drive afterward. Watch for the client who plans to avoid the highway entirely; the plan is for driving it, and a shorter stretch is a fine start.', '[{"id": "f0", "type": "textarea", "label": "The stretch of road, and the exit before and after it:"}, {"id": "f1", "type": "textarea", "label": "What my body does there, and what it tells me to do:"}, {"id": "f2", "type": "textarea", "label": "My steps, in order (lane, exit named aloud, exhale per marker, hands, radio):"}, {"id": "f3", "type": "textarea", "label": "The known song or voice I will have on:"}, {"id": "f4", "type": "textarea", "label": "After the drive: what the surge did, and when it eased:"}, {"id": "f5", "type": "textarea", "label": "The stretch I will drive next:"}]'::jsonb, array['panic attacks', 'panic', 'pacing']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('paced-breathing-in-the-movie-theater-dark-card', 'Paced Breathing in the Movie Theater Dark Card', 'dbt'::resource_kind, 'A Paced Breathing card for the dark, crowded theater where the client cannot leave without climbing over a row.', 'Use it to give a client a breath they can run in the dark without anyone noticing.', array['Adults', 'Teens']::text[], 'Five minutes, during one movie', 'A theater has every ingredient: dark, crowd, noise, and a row between the client and the aisle. The card sets the breath before the lights go down (in for four, out for six, through the nose, a hand on the armrest), and asks the client to run it at the first flicker of the surge and again at the climax of the film, when the sound is loudest. It records the peak and when it eased. Watch for the client who sits at the end of the aisle every time; a middle seat is a later step, named as such.', '[{"id": "f0", "type": "textarea", "label": "The movie, the seat, and how I felt walking in:"}, {"id": "f1", "type": "textarea", "label": "The breath I set before the lights went down:"}, {"id": "f2", "type": "textarea", "label": "When the first flicker came, and what the breath did:"}, {"id": "f3", "type": "textarea", "label": "The loudest part of the film, and my peak (0 to 10):"}, {"id": "f4", "type": "textarea", "label": "When the surge eased, and what I noticed about staying in the seat:"}]'::jsonb, array['panic attacks', 'breathing', 'distress tolerance']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('spin-and-steady-dizzy-sensation-group-game', 'Spin and Steady Dizzy Sensation Group Game', 'game'::resource_kind, 'A group game where players spin on the spot for a count, stop, and name what the dizziness feels like before it fades.', 'Use it to let a group practice having a strong body sensation on purpose and watching it pass.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes with debrief', 'Players stand with space around them. On go, everyone spins slowly for a count of ten, stops, plants their feet, and the leader asks three volunteers to name the sensation in plain words while it fades. The group times how long until each volunteer says steady. Three rounds, with players allowed to sit out any round. The debrief asks what the mind said during the spin and what the body actually did after. Clear the floor and check for anyone who should skip spinning. Watch for the player who stops early every time; a count of five is still a turn.', '[{"id": "f0", "type": "textarea", "label": "Round one: what the dizziness felt like, in plain words:"}, {"id": "f1", "type": "textarea", "label": "How long until you felt steady, and what your mind said in that time:"}, {"id": "f2", "type": "textarea", "label": "Round two or three: what changed about the sensation or the waiting?"}, {"id": "f3", "type": "textarea", "label": "A sensation in your week that feels like this, and what you usually do:"}, {"id": "f4", "type": "textarea", "label": "What the game says about waiting for a sensation to fade on its own:"}]'::jsonb, array['panic attacks', 'game', 'body awareness']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('different-rules-at-grandma-s-house-reentry-plan-sheet', 'Different Rules at Grandma''s House Reentry Plan Sheet', 'worksheet'::resource_kind, 'A plan for the first evening home after a stay with grandparents whose rules were looser, so the return does not become a fight.', 'Use it to help a parent reset routines after a visit without blaming the child or the grandparents.', array['Adults']::text[], '15 minutes on the drive home', 'Children come home from a grandparent''s house with new bedtimes, new snacks and a new sense of what is allowed, and the first evening home is where parents lose their temper. The sheet names what will have shifted, the one or two rules the parent will hold tonight and the ones that can wait until tomorrow, and the sentence that honors the fun without undoing the home. Watch for the parent who wants to fix everything the first night; the sheet picks two.', '[{"id": "f0", "type": "textarea", "label": "What will have shifted during the visit (bedtime, screens, snacks, manners):"}, {"id": "f1", "type": "textarea", "label": "The one or two rules I will hold tonight, no matter what:"}, {"id": "f2", "type": "textarea", "label": "The ones I will let go until tomorrow:"}, {"id": "f3", "type": "textarea", "label": "What I will say about the visit that honors the fun:"}, {"id": "f4", "type": "textarea", "label": "What I will say to my parents or in-laws about it, if anything, and when:"}, {"id": "f5", "type": "textarea", "label": "How the first evening actually went:"}]'::jsonb, array['parenting', 'routines', 'family']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('values-when-the-toddler-throws-dinner-on-the-floor-page', 'Values When the Toddler Throws Dinner on the Floor Page', 'act'::resource_kind, 'A values page for the moment a toddler sweeps a plate off the table and a parent has three seconds to decide who to be.', 'Use it to help a parent find the value under the mess and act on it in the heat of the moment.', array['Adults']::text[], '15 minutes, then a line after each dinner', 'The plate on the floor is a test nobody passes every time. The page asks the parent what they want to stand for in that moment (steadiness, warmth, firmness, humor), what their body wants to do instead, and the one small act that would be their value in motion: a flat voice, a towel handed over, a sentence. It records the next three dinners. Watch for the parent who writes a value and grades themselves against it; the page is a direction, and the dinners are practice.', '[{"id": "f0", "type": "textarea", "label": "The moment: what the plate does, and what my body wants to do:"}, {"id": "f1", "type": "textarea", "label": "What I want to stand for in that moment, in one or two words:"}, {"id": "f2", "type": "textarea", "label": "The one small act that is that value in motion:"}, {"id": "f3", "type": "textarea", "label": "Dinner one, two and three: what I did, and how close it was:"}, {"id": "f4", "type": "textarea", "label": "What I notice about myself when I act on the value even once:"}]'::jsonb, array['parenting', 'values', 'committed action']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('validation-when-the-teen-says-i-do-not-understand-card', 'Validation When the Teen Says I Do Not Understand Card', 'dbt'::resource_kind, 'A Validation card for the sentence every parent hears from a teenager, with the levels of validation that keep the door open.', 'Use it to help a parent answer you do not understand without proving that they do.', array['Adults']::text[], '15 minutes to prepare, then the next time it happens', 'You do not understand is usually true in some way and a door slam in another. The card prepares the parent to answer without a counterargument: pay attention, reflect back what they heard, name what makes sense about the feeling, and say the part that is true (I was not there, I have not lived your year). It records what the teen did after. Watch for the parent who validates and then adds but; the but undoes the sentence before it.', '[{"id": "f0", "type": "textarea", "label": "What my teen said, and what my first urge was:"}, {"id": "f1", "type": "textarea", "label": "What I reflected back, in their words:"}, {"id": "f2", "type": "textarea", "label": "What made sense about their feeling, said out loud:"}, {"id": "f3", "type": "textarea", "label": "The part of ''you do not understand'' that is actually true, said plainly:"}, {"id": "f4", "type": "textarea", "label": "What my teen did or said after, and what the door felt like:"}]'::jsonb, array['parenting', 'validation', 'interpersonal effectiveness']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('returning-to-work-pumping-and-handoff-logistics-sheet', 'Returning to Work Pumping and Handoff Logistics Sheet', 'worksheet'::resource_kind, 'A logistics sheet for the first week back at work after a baby: the pumping schedule, the supplies, the handoff and the moment of leaving.', 'Use it to give a new parent a plan for the week their mind keeps rehearsing as a disaster.', array['Adults']::text[], '30 minutes the weekend before', 'The return to work is often dreaded in pieces: the pump room, the bag, the daycare door, the drive. The sheet gives each piece a line: the schedule and where it happens, what goes in the bag the night before, who does the morning handoff and what the goodbye looks like, and the person to text at ten. Watch for the parent who plans every piece and skips the goodbye; the moment at the door deserves its own line and its own sentence.', '[{"id": "f0", "type": "textarea", "label": "My pumping or feeding schedule, and where each one happens at work:"}, {"id": "f1", "type": "textarea", "label": "What goes in the bag the night before, as a list:"}, {"id": "f2", "type": "textarea", "label": "Who does the morning handoff, and what the goodbye looks like:"}, {"id": "f3", "type": "textarea", "label": "The sentence I will say at the door, to my baby and to myself:"}, {"id": "f4", "type": "textarea", "label": "Who I will text at ten, and what I need them to say back:"}, {"id": "f5", "type": "textarea", "label": "After day one: what went better than I feared, and what I will change:"}]'::jsonb, array['perinatal and postpartum', 'planning', 'work']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('needing-help-with-the-baby-means-i-am-failing-sheet', 'Needing Help With the Baby Means I Am Failing Sheet', 'cbt'::resource_kind, 'A belief sheet for the new parent who reads every offered or accepted hand as proof they cannot do this themselves.', 'Use it to help a new parent test the rule that help equals failure.', array['Adults']::text[], '15 minutes', 'A new parent who refuses help is often guarding a belief, not a baby. The sheet writes the belief and its strength, the help that was offered or taken this week, and what the belief says each one meant. It then asks what the client believes about other parents who take help and what a baby actually needs from a parent who is rested. The last box is one piece of help to accept this week. Watch for the client who accepts help and apologizes for it afterward.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words, and how much I believe it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "The help offered or taken this week, and what my mind said each one meant:"}, {"id": "f2", "type": "textarea", "label": "What I think about other parents who take help:"}, {"id": "f3", "type": "textarea", "label": "What my baby actually gets from a parent who has slept and eaten:"}, {"id": "f4", "type": "textarea", "label": "One piece of help I will accept this week, without apologizing for it:"}, {"id": "f5", "type": "textarea", "label": "How it went:"}]'::jsonb, array['perinatal and postpartum', 'core beliefs', 'self-criticism']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('tired-mind-as-a-fogged-windshield-at-dawn-page', 'Tired Mind as a Fogged Windshield at Dawn Page', 'act'::resource_kind, 'A defusion page that pictures the exhausted postpartum mind as a fogged windshield: hard to see through, clearing slowly, not broken.', 'Use it to help a new parent treat the dark thoughts of a sleepless dawn as fog rather than fact.', array['Adults']::text[], '10 minutes, then a line each morning', 'At five in the morning after a night of feeds, the thoughts are bleak and sound like truth. The page asks the client to write the dawn thoughts as fog on the glass, notice how the same thoughts read at noon, and name what clears the windshield a little: light, a warm drink, a text answered. It records one fogged morning and what the glass looked like by ten. Watch for a thought that stays bleak at noon too; that is for session, and 988 is on the sheet for a reason.', '[{"id": "f0", "type": "textarea", "label": "The thoughts that show up on the fogged dawn glass:"}, {"id": "f1", "type": "textarea", "label": "How the same thoughts read to me at noon:"}, {"id": "f2", "type": "textarea", "label": "What clears the windshield a little (light, warmth, a person):"}, {"id": "f3", "type": "textarea", "label": "One fogged morning this week, and what the glass looked like by ten:"}, {"id": "f4", "type": "textarea", "label": "If a thought stays dark at noon, who I will tell, and 988 (call or text) if I need it now:"}]'::jsonb, array['perinatal and postpartum', 'defusion', 'sleep']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-the-baby-s-clean-laundry-smell-card', 'Self-Soothe With the Baby''s Clean Laundry Smell Card', 'dbt'::resource_kind, 'A Self-Soothe card for folding the baby''s clean laundry, using the smell and the warmth as a two-minute rest in a long day.', 'Use it to turn a chore a new parent already does into a soothing skill.', array['Adults']::text[], 'Two minutes, during one load of laundry', 'A new parent has no time for a skill but plenty of laundry. The card asks the client to pause with a warm folded item against the face for a slow breath, notice the smell, the warmth and the softness, and let the rest of the pile wait for two minutes. It records the distress before and after and what the mind did. Watch for the client who folds faster to earn the pause; the pause is in the middle, not at the end.', '[{"id": "f0", "type": "textarea", "label": "Where I was, and what kind of day it had been:"}, {"id": "f1", "type": "textarea", "label": "My distress before (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "What I noticed with the warm item against my face (smell, warmth, softness):"}, {"id": "f3", "type": "textarea", "label": "Where my mind went, and what brought it back:"}, {"id": "f4", "type": "textarea", "label": "My distress after (0 to 10), and what the two minutes gave me:"}]'::jsonb, array['perinatal and postpartum', 'self-soothing', 'self-care']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('night-feed-shifts-and-morning-handoff-plan-for-new-parents', 'Night Feed Shifts and Morning Handoff Plan for New Parents', 'couples'::resource_kind, 'A shift plan for partners through the night feeds, with the handoff moment written down so nobody keeps score at 6 a.m.', 'Use it to help new parents share the nights fairly and stop the morning resentment before it starts.', array['Couples']::text[], '20 minutes, then one week', 'Two tired parents keeping a mental tally of who got up is a fight waiting for daylight. Each partner says what they can realistically take on at night and what they need to function the next day. They set the shifts, the handoff time, and the one sentence said at the handoff. After a week they revise together. Watch for the partner who takes every night to be generous and is furious by Friday; the sheet is for shifts, not sacrifices.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I can realistically take at night, and what I need the next day:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can realistically take at night, and what I need the next day:"}, {"id": "f2", "type": "textarea", "label": "Our shifts, and the handoff time:"}, {"id": "f3", "type": "textarea", "label": "The sentence we say at the handoff:"}, {"id": "f4", "type": "textarea", "label": "After one week, each of us: what to change:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'fairness']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('things-i-know-how-to-do-nobody-taught-me-inventory-sheet', 'Things I Know How to Do Nobody Taught Me Inventory Sheet', 'worksheet'::resource_kind, 'An inventory of skills the client taught themselves, from fixing a toilet to calming a friend, collected as evidence of competence.', 'Use it to help a client who discounts every skill they have see the ones they built alone.', array['Adults', 'Teens']::text[], '20 minutes, then add to it for a week', 'Clients with low self-regard count what they were taught and ignore what they worked out alone. The sheet asks for the things they figured out without a class or a parent: practical, social, creative, quiet. For each, how they learned it and when they last used it. The last box is the skill they are quietly proud of. Watch for the client who writes nothing for ten minutes; start with what they did this morning.', '[{"id": "f0", "type": "textarea", "label": "Practical things I taught myself (tools, cooking, fixing, finding my way):"}, {"id": "f1", "type": "textarea", "label": "People things I taught myself (calming someone, reading a room, asking for help):"}, {"id": "f2", "type": "textarea", "label": "Creative or quiet things I taught myself:"}, {"id": "f3", "type": "textarea", "label": "For one of them: how I learned it, and when I last used it:"}, {"id": "f4", "type": "textarea", "label": "The one on this list I am quietly proud of, and why:"}, {"id": "f5", "type": "textarea", "label": "What this list says about me that my usual story leaves out:"}]'::jsonb, array['self-esteem', 'strengths', 'evidence']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('being-corrected-means-i-am-incompetent-thought-record', 'Being Corrected Means I Am Incompetent Thought Record', 'cbt'::resource_kind, 'A thought record for the small correction at work or school that turns, within minutes, into a judgment of the whole person.', 'Use it to help a client separate a fixed mistake from a verdict on their ability.', array['Adults', 'Teens']::text[], '15 minutes after the next correction', 'A correction is information about one thing and lands as information about everything. The record writes the correction as it was said, the thought, the emotion and its strength, then the evidence: what the client has done right in the same role, how often the person who corrected them is corrected too, what the correction would mean about a colleague. The balanced thought names the mistake and the person separately. Watch for the client who agrees with the correction and the verdict both.', '[{"id": "f0", "type": "textarea", "label": "What was corrected, in the words that were used:"}, {"id": "f1", "type": "textarea", "label": "The thought about me, word for word, and how much I believe it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The emotion, and how strong (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What I have done right in this same role recently:"}, {"id": "f4", "type": "textarea", "label": "What this correction would mean about a colleague I respect:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought that names the mistake and me separately:"}]'::jsonb, array['self-esteem', 'thought record', 'work']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('self-worth-as-the-stage-not-the-review-page', 'Self-Worth as the Stage Not the Review Page', 'act'::resource_kind, 'A self-as-context page that places the client as the stage every performance happens on, not the review printed the next morning.', 'Use it to help a client find a self that is not changed by praise or criticism.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'A client whose worth rises and falls with every reaction is living in the reviews. The page asks for this week''s reviews, good and bad, then for the stage: what was there before any of them and will be there after. It asks what the stage does while the reviews are read and what the client would do this week if they were the stage. Watch for the client who wants only good reviews; the page is about standing under either.', '[{"id": "f0", "type": "textarea", "label": "This week''s reviews: the praise and the criticism I took to heart:"}, {"id": "f1", "type": "textarea", "label": "How I felt after the best one, and after the worst:"}, {"id": "f2", "type": "textarea", "label": "What was there before any of them and is still here now:"}, {"id": "f3", "type": "textarea", "label": "What the stage does while the reviews are being read:"}, {"id": "f4", "type": "textarea", "label": "One thing I would do this week if I were the stage and not the review:"}]'::jsonb, array['self-esteem', 'self-as-context', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('fast-skill-when-the-group-picks-the-restaurant-card', 'FAST Skill When the Group Picks the Restaurant Card', 'dbt'::resource_kind, 'A FAST card for the group chat choosing a restaurant, when the client''s preference disappears the moment someone else speaks.', 'Use it to help a client keep self-respect in a small group decision.', array['Adults', 'Teens']::text[], 'Ten minutes, during the next group plan', 'The restaurant does not matter; the vanishing does. The card walks the client through FAST in the group chat: be fair to themselves and the others, no apologies for having a preference, stick to the value of being counted, be truthful about what they actually want. It records what they typed, what happened, and how the dinner felt. Watch for the client who names a preference and immediately adds but anything is fine; the apology line is where the practice is.', '[{"id": "f0", "type": "textarea", "label": "What I actually wanted, before anyone else spoke:"}, {"id": "f1", "type": "textarea", "label": "Fair: how I can state it without stepping on anyone:"}, {"id": "f2", "type": "textarea", "label": "No apologies: the sentence without the softener I usually add:"}, {"id": "f3", "type": "textarea", "label": "Stick to values: what being counted means to me here:"}, {"id": "f4", "type": "textarea", "label": "Truthful: what I typed, word for word, and what happened:"}, {"id": "f5", "type": "textarea", "label": "How dinner felt, whichever restaurant it was:"}]'::jsonb, array['self-esteem', 'FAST', 'interpersonal effectiveness']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('secret-admirer-notes-guess-who-wrote-it-game', 'Secret Admirer Notes Guess Who Wrote It Game', 'game'::resource_kind, 'A group game where everyone writes an anonymous note naming a strength in another member, and the group guesses who wrote each one.', 'Use it to let a group give and receive specific praise with the awkwardness turned into a guessing game.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Each member draws a name from a hat and writes one anonymous note about a strength they have seen in that person, with one specific example. The notes go into a bowl; the leader reads each aloud and the group guesses the writer, then the recipient says one sentence back. Nobody guesses their own note. The debrief asks what it was like to be described specifically and what it was like to describe someone. Watch for the member who deflects their note with a joke; ask them to read it aloud once.', '[{"id": "f0", "type": "textarea", "label": "The strength you wrote about, and the example you gave:"}, {"id": "f1", "type": "textarea", "label": "The note written about you, in your own words:"}, {"id": "f2", "type": "textarea", "label": "What it was like to hear it read to the group:"}, {"id": "f3", "type": "textarea", "label": "The sentence you said back:"}, {"id": "f4", "type": "textarea", "label": "A strength someone named in another person that you had not noticed:"}]'::jsonb, array['self-esteem', 'game', 'group']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('office-holiday-party-first-fifteen-minutes-plan-sheet', 'Office Holiday Party First Fifteen Minutes Plan Sheet', 'worksheet'::resource_kind, 'A plan for the first fifteen minutes of the office party, when the client stands in the door with a coat on and nowhere to go.', 'Use it to give a client a script for the arrival so the rest of the party can take care of itself.', array['Adults']::text[], '15 minutes the day before', 'The arrival is the hardest quarter hour and the one most planned around avoiding. The sheet writes it minute by minute: where the coat goes, the first person to find, the first sentence, the drink or plate to hold, and the spot in the room to stand. It sets the earliest acceptable leaving time and the latest. Afterward it records what the first fifteen minutes were actually like. Watch for the client who arrives late to shrink the party; arriving early to an emptier room is often easier.', '[{"id": "f0", "type": "textarea", "label": "When I will arrive, and where my coat will go:"}, {"id": "f1", "type": "textarea", "label": "The first person I will find, and my first sentence to them:"}, {"id": "f2", "type": "textarea", "label": "What I will hold, and where in the room I will stand:"}, {"id": "f3", "type": "textarea", "label": "The earliest I may leave, and the latest I will stay:"}, {"id": "f4", "type": "textarea", "label": "What the first fifteen minutes were actually like:"}, {"id": "f5", "type": "textarea", "label": "The moment it got easier, if it did:"}]'::jsonb, array['social anxiety', 'planning', 'work']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('they-did-not-laugh-so-the-joke-bombed-thought-record', 'They Did Not Laugh So the Joke Bombed Thought Record', 'cbt'::resource_kind, 'A thought record for the joke that got a half-smile instead of a laugh and the replay that runs for the rest of the night.', 'Use it to help a client measure a social moment by what happened rather than by the replay.', array['Adults', 'Teens']::text[], '15 minutes that evening', 'A joke that lands softly becomes, in the replay, a joke that bombed in front of everyone. The record writes the moment as it happened, the thought, the emotion and its strength, then the evidence: what the other person did next, whether the conversation continued, how the client reacts when someone else''s joke lands softly. The balanced thought is one sentence the client can use to stop the replay. Watch for the client who wants to never joke again; the record is about the replay, not the joke.', '[{"id": "f0", "type": "textarea", "label": "The joke, and what the other person actually did (face, words, what came next):"}, {"id": "f1", "type": "textarea", "label": "The thought, word for word, and how much I believe it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The emotion, and how strong (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "Whether the conversation continued, and what it was about:"}, {"id": "f4", "type": "textarea", "label": "What I think when someone else''s joke gets a half-smile:"}, {"id": "f5", "type": "textarea", "label": "One sentence to stop the replay with:"}]'::jsonb, array['social anxiety', 'thought record', 'post-event processing']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('social-mind-as-a-referee-whistling-every-word-page', 'Social Mind as a Referee Whistling Every Word Page', 'act'::resource_kind, 'A defusion page that pictures the self-monitoring mind as a referee who stops play for every word the client says.', 'Use it to help a client let the whistle blow and keep playing.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'A conversation with a referee in it never gets going. The page asks the client to write the referee''s calls (too loud, too quiet, wrong word, weird face), notice the whistle in the body, and practice playing through: finishing the sentence, staying in the conversation, letting the call stand unreviewed. It records one conversation played through the whistle. Watch for the client who wants to fire the referee; the aim is a game that continues with the whistle in it.', '[{"id": "f0", "type": "textarea", "label": "The referee''s most frequent calls, in his words:"}, {"id": "f1", "type": "textarea", "label": "What the whistle feels like in my body mid-conversation:"}, {"id": "f2", "type": "textarea", "label": "What I usually do when it blows (stop, apologize, go quiet, leave):"}, {"id": "f3", "type": "textarea", "label": "One conversation this week I played through the whistle:"}, {"id": "f4", "type": "textarea", "label": "What the game was like when I kept playing:"}]'::jsonb, array['social anxiety', 'defusion', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('dear-man-asking-the-group-to-repeat-the-plan-card', 'DEAR MAN Asking the Group to Repeat the Plan Card', 'dbt'::resource_kind, 'A DEAR MAN card for the moment the client missed what the group decided and would rather guess than ask them to say it again.', 'Use it to help a client make a small, exposed request in front of several people.', array['Adults', 'Teens']::text[], 'Ten minutes to prepare, then the next time it happens', 'Asking a group to repeat something feels like admitting to not belonging. The card scripts it: describe what was missed, express the wish to get it right, assert the request in one sentence, reinforce that it saves everyone a mix-up, then stay mindful, look confident, negotiate if the answer is a shrug. It records the group''s actual response. Watch for the client who asks one person privately afterward instead; that is a fine step, named as the step before this one.', '[{"id": "f0", "type": "textarea", "label": "Describe: what I missed, in facts:"}, {"id": "f1", "type": "textarea", "label": "Express: why I want to get it right, in one sentence:"}, {"id": "f2", "type": "textarea", "label": "Assert: the request, said plainly to the group:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what everyone gains from me asking:"}, {"id": "f4", "type": "textarea", "label": "What the group actually did when I asked:"}, {"id": "f5", "type": "textarea", "label": "What my mind predicted, next to what happened:"}]'::jsonb, array['social anxiety', 'DEAR MAN', 'interpersonal effectiveness']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('introduce-your-neighbor-two-facts-circle-game', 'Introduce Your Neighbor Two Facts Circle Game', 'game'::resource_kind, 'A circle game where each player interviews the person next to them for two minutes and then introduces them to the group with two facts.', 'Use it to let a new group talk one to one first and speak to the room second, with someone else''s words.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Players pair with their neighbor and take two minutes each to learn two facts about them, anything but their job. Then the circle goes round and each player introduces their neighbor to the group with the two facts and the neighbor''s name, while the neighbor sits still and is talked about. The debrief asks which was harder, being introduced or introducing, and what the body did while waiting for their turn. Watch for the player who introduces their neighbor in one word; ask for the second fact.', '[{"id": "f0", "type": "textarea", "label": "The two facts you learned about your neighbor:"}, {"id": "f1", "type": "textarea", "label": "The two facts your neighbor shared about you, and whether they got them right:"}, {"id": "f2", "type": "textarea", "label": "Which was harder: introducing, or sitting still while being introduced?"}, {"id": "f3", "type": "textarea", "label": "What your body did while your turn approached:"}, {"id": "f4", "type": "textarea", "label": "Someone in the circle you now know two things about and did not before:"}]'::jsonb, array['social anxiety', 'game', 'social skills']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('writing-the-holiday-card-i-would-have-sent-them-sheet', 'Writing the Holiday Card I Would Have Sent Them Sheet', 'worksheet'::resource_kind, 'A sheet for writing the holiday card the client would have sent the person they lost, and deciding what to do with it.', 'Use it to give a client a place for the words that have no address this year.', array['Adults', 'Teens']::text[], '30 minutes, in session or at home', 'The card list has a name on it with no address this year, and the client still has things to say. The sheet gives the card room: what they would have written this year, the news they would have wanted that person to know, the question they would have asked them, and the sign-off. The last box decides what happens to it: kept, read aloud, placed somewhere. Watch for the client who writes the card and then wants to send it to the family; that is a separate decision worth its own conversation.', '[{"id": "f0", "type": "textarea", "label": "The opening line I would have written this year:"}, {"id": "f1", "type": "textarea", "label": "The news from my year I most want them to know:"}, {"id": "f2", "type": "textarea", "label": "The question I would have asked them:"}, {"id": "f3", "type": "textarea", "label": "How I would have signed it:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the card (keep, read aloud, place it somewhere):"}, {"id": "f5", "type": "textarea", "label": "What writing it was like:"}]'::jsonb, array['grief and loss', 'rituals', 'holidays']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('missing-the-funeral-means-i-failed-them-thought-record', 'Missing the Funeral Means I Failed Them Thought Record', 'cbt'::resource_kind, 'A thought record for the client who could not be at the funeral and carries it as proof they let the person down.', 'Use it to help a client put the missed funeral beside the whole record of the relationship.', array['Adults', 'Teens']::text[], '20 minutes in session', 'Missing a funeral, for distance or illness or money or a decision made in shock, becomes a sentence the client serves for years. The record writes what kept them away, the thought, the emotion and its strength, then the evidence: what they did for the person while they lived, what the person would say about the absence, how the client regards others who could not be there. The balanced thought is written slowly. Watch for the client who wants to be forgiven by the sheet; the sheet is for seeing the whole record.', '[{"id": "f0", "type": "textarea", "label": "What kept me away, in facts, without defending it:"}, {"id": "f1", "type": "textarea", "label": "The thought, word for word, and how much I believe it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The emotion, and how strong (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "What I did for them while they were alive, the small things too:"}, {"id": "f4", "type": "textarea", "label": "What they would say to me about not being there:"}, {"id": "f5", "type": "textarea", "label": "A thought that holds the absence and the whole relationship together:"}]'::jsonb, array['grief and loss', 'thought record', 'guilt']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('grief-as-snow-that-falls-on-everything-page', 'Grief as Snow That Falls on Everything Page', 'act'::resource_kind, 'An acceptance page that pictures grief as snow: it covers the whole landscape and still leaves the client able to walk in it.', 'Use it to help a client stop waiting for the snow to melt before living in the landscape.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'Fresh grief covers everything, the good days and the errands alike. The page asks the client to describe the snow this week, what it has covered that they miss, and what they have still been able to do in it: a drive, a meal, a laugh. It then asks what walking in the snow looks like tomorrow. Watch for the client who hears this as pressure to be fine; the snow is allowed to be deep, and the walk can be to the mailbox.', '[{"id": "f0", "type": "textarea", "label": "What the snow is covering this week:"}, {"id": "f1", "type": "textarea", "label": "What I miss most under it:"}, {"id": "f2", "type": "textarea", "label": "What I have still done in the snow (a drive, a meal, a laugh):"}, {"id": "f3", "type": "textarea", "label": "What walking in it looks like tomorrow, at whatever pace:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the landscape that is still there under the snow:"}]'::jsonb, array['grief and loss', 'acceptance', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('improve-the-moment-with-one-photo-of-them-card', 'IMPROVE the Moment With One Photo of Them Card', 'dbt'::resource_kind, 'An IMPROVE the Moment card for a grief wave, using one chosen photo and the imagery, meaning and one-thing lines of the skill.', 'Use it to give a client a way through a wave that honors the person and passes.', array['Adults', 'Teens']::text[], 'Ten minutes, when a wave comes', 'A grief wave in a parking lot or a kitchen needs a skill that fits in a pocket. The card has the client choose one photo in advance, and when the wave comes: imagery (where the photo was taken, what the air was like), meaning (what that day gave them), one thing in the moment (the breath, the ground), and a word of encouragement in the person''s voice. It records the wave''s peak and ebb. Watch for the client who scrolls through hundreds of photos; the one chosen photo is the skill.', '[{"id": "f0", "type": "textarea", "label": "The photo I chose, and why this one:"}, {"id": "f1", "type": "textarea", "label": "Imagery: where it was taken, and what that day felt like:"}, {"id": "f2", "type": "textarea", "label": "Meaning: what that day gave me that I still have:"}, {"id": "f3", "type": "textarea", "label": "One thing in the moment: what I noticed in my body and the room:"}, {"id": "f4", "type": "textarea", "label": "The encouraging word, in their voice:"}, {"id": "f5", "type": "textarea", "label": "The wave: its peak (0 to 10), and when it ebbed:"}]'::jsonb, array['grief and loss', 'IMPROVE', 'distress tolerance']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('painted-rock-for-their-garden-spot-craft', 'Painted Rock for Their Garden Spot Craft', 'kids'::resource_kind, 'A craft where a child paints a rock for the person or pet they lost and chooses a spot outside to keep it.', 'Use it to give a grieving child something to make with their hands and a place to visit.', array['Children']::text[], '30 minutes, plus a walk to place it', 'A child''s grief needs an object and a place. The child chooses a smooth rock, paints it with a color, a picture or a word that belongs to the person or pet, and the parent helps seal it. Together they choose the spot: a garden, a pot on the step, a windowsill if outside is not possible. The parent lets the child decide when to visit it and goes along when asked. In session, ask what the rock looks like and what the child says when they visit. Watch for the parent who paints the rock; the child''s picture is the one that counts.', '[{"id": "f0", "type": "textarea", "label": "Paint your rock. What color or picture did you choose, and why?"}, {"id": "f1", "type": "textarea", "label": "Where will your rock live? Draw the spot."}, {"id": "f2", "type": "textarea", "label": "What do you want to say when you visit it?"}, {"id": "f3", "type": "textarea", "label": "What do you remember about them when you look at it?"}, {"id": "f4", "type": "textarea", "label": "Parent: what my child painted, and what I did while they worked:"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('read-receipt-with-no-reply-thought-record', 'Read Receipt With No Reply Thought Record', 'cbt'::resource_kind, 'A thought record for the message marked read with no reply and the hours of meaning the client builds on it.', 'Use it to help a client notice how much certainty they take from two small words on a screen.', array['Adults', 'Teens']::text[], '10 minutes, before sending the follow-up', 'Read at 2:14 and no reply by dinner is enough for most clients to write a verdict. The record writes the message and the receipt, the thought, the emotion and its strength, then the evidence: how often the client reads and does not reply right away, what this person''s reply habits are, what else is happening in their day. The balanced thought is written before any follow-up is sent. Watch for the client who sends three follow-ups while filling in the sheet.', '[{"id": "f0", "type": "textarea", "label": "The message I sent, and when it was read:"}, {"id": "f1", "type": "textarea", "label": "The thought, word for word, and how much I believe it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The emotion, and how strong (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "How often I read a message and do not reply right away, and why:"}, {"id": "f4", "type": "textarea", "label": "What I know about this person''s reply habits and their day:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and my decision about a follow-up:"}]'::jsonb, array['relationship issues', 'thought record', 'mind reading']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('resentment-as-a-tab-left-open-all-day-page', 'Resentment as a Tab Left Open All Day Page', 'act'::resource_kind, 'A defusion page that pictures a grudge as a browser tab left open all day, quietly using memory in the background.', 'Use it to help a client notice what the open tab costs and decide what to do with it on purpose.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'A resentment does not need attention to run; it runs in the background and slows everything else. The page asks the client to name the tab, how long it has been open, what it costs during an ordinary day, and the three honest options: close it, deal with it, or leave it open knowing the cost. It records one day of noticing when the tab comes to the front. Watch for the client who closes the tab and reopens it an hour later; that is the noticing practice, not a failure.', '[{"id": "f0", "type": "textarea", "label": "The tab: the resentment in a few words, and how long it has been open:"}, {"id": "f1", "type": "textarea", "label": "What it costs me on an ordinary day:"}, {"id": "f2", "type": "textarea", "label": "When it comes to the front, and what brings it there:"}, {"id": "f3", "type": "textarea", "label": "My three options, honestly: close, deal with it, or leave it open knowing the cost:"}, {"id": "f4", "type": "textarea", "label": "What I chose today, and what the rest of the day was like:"}]'::jsonb, array['relationship issues', 'defusion', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('give-skills-with-the-sibling-who-always-one-ups-card', 'GIVE Skills With the Sibling Who Always One-Ups Card', 'dbt'::resource_kind, 'A GIVE card for the sibling who answers every piece of news with something bigger of their own.', 'Use it to help a client keep a relationship warm without feeding the contest.', array['Adults']::text[], 'Ten minutes before the next call or visit', 'The one-upping sibling turns every exchange into a contest, and the client leaves feeling smaller. The card plans GIVE for the next conversation: gentle (no jab back), interested (one real question about their bigger thing), validate (what makes sense about their wanting to be seen), easy manner (a light tone when the contest starts). It records how the exchange went and what the client did not say. Watch for the client who uses GIVE to win; the aim is the relationship, not the round.', '[{"id": "f0", "type": "textarea", "label": "The last one-up, and what I wanted to say back:"}, {"id": "f1", "type": "textarea", "label": "Gentle: what I will not say this time:"}, {"id": "f2", "type": "textarea", "label": "Interested: the real question I will ask about their thing:"}, {"id": "f3", "type": "textarea", "label": "Validate: what makes sense about their need to be seen:"}, {"id": "f4", "type": "textarea", "label": "Easy manner: how I will sound when the contest starts:"}, {"id": "f5", "type": "textarea", "label": "How the conversation actually went:"}]'::jsonb, array['relationship issues', 'GIVE', 'family']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('phone-password-privacy-and-trust-talk-for-partners', 'Phone Password Privacy and Trust Talk for Partners', 'couples'::resource_kind, 'A structured talk for partners about phone passwords, privacy and trust, with both partners'' needs written before the rule.', 'Use it to help a couple decide what phone privacy means for them instead of fighting about a locked screen.', array['Couples']::text[], '40 minutes in session', 'A locked phone means privacy to one partner and secrecy to the other, and the fight is about the meaning, not the password. Each partner writes what a locked or open phone means to them and what they are afraid of in the other version. Then they look at what trust is built on in this relationship besides the phone, and write an agreement they can both keep. Watch for the partner who wants access as proof; ask what the proof would settle and for how long.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what a locked phone means to me, and what I fear about an open one:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what a locked phone means to me, and what I fear about an open one:"}, {"id": "f2", "type": "textarea", "label": "What trust is built on in our relationship, apart from phones:"}, {"id": "f3", "type": "textarea", "label": "Our agreement about passwords and access, in plain words:"}, {"id": "f4", "type": "textarea", "label": "What each of us will do when the agreement feels uncomfortable:"}]'::jsonb, array['relationship issues', 'couples', 'boundaries']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('crowded-elevator-exit-options-plan-sheet', 'Crowded Elevator Exit Options Plan Sheet', 'worksheet'::resource_kind, 'A plan for the crowded elevator and other tight public spaces, listing the client''s options before the doors close.', 'Use it to help a client keep choices in a small space where the body expects to have none.', array['Adults', 'Teens']::text[], '15 minutes in session', 'A crowded elevator can take a client''s body back to a time with no way out. The sheet lists the spaces that do this, the options the client actually has in each (wait for the next one, stand by the panel, take the stairs, step off early), what to hold or focus on, and the sentence that reminds them the doors open. Keep it on the stabilizing side; nothing here asks about what happened. Watch for the client who plans to avoid all elevators; the stairs are an option, not the only one.', '[{"id": "f0", "type": "textarea", "label": "The tight spaces that set my body off:"}, {"id": "f1", "type": "textarea", "label": "My options in each, written out (wait, stand by the panel, stairs, step off early):"}, {"id": "f2", "type": "textarea", "label": "What I will hold or look at while the doors are closed:"}, {"id": "f3", "type": "textarea", "label": "The sentence that reminds me the doors open:"}, {"id": "f4", "type": "textarea", "label": "One tight space this week, and which option I used:"}]'::jsonb, array['sexual abuse', 'safety', 'grounding']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('not-remembering-it-all-means-it-did-not-count-check-sheet', 'Not Remembering It All Means It Did Not Count Check Sheet', 'cbt'::resource_kind, 'A gentle check sheet for the belief that gaps in memory mean the client''s experience does not count or cannot be trusted.', 'Use it to help a client hold the gaps in their memory without letting the gaps erase their experience.', array['Adults', 'Teens']::text[], '20 minutes in session', 'Many clients doubt themselves because the memory has holes, and the doubt becomes a reason to stay silent. The sheet writes the belief and its strength, then what the client knows about how memory works under fear, what they do remember without needing details on the page, and whether a friend with gaps would be believed by them. The last box is a sentence that holds the gaps and the truth together. Complete it in session; nothing here asks for what happened.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words, and how much I believe it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "What I know about how memory works when a person is frightened:"}, {"id": "f2", "type": "textarea", "label": "What I do know for sure, without writing any details here:"}, {"id": "f3", "type": "textarea", "label": "Whether I would believe a friend whose memory had gaps, and why:"}, {"id": "f4", "type": "textarea", "label": "A sentence that holds the gaps and what I know, together:"}]'::jsonb, array['sexual abuse', 'stabilizing', 'core CBT']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('safety-as-a-garden-i-tend-not-a-wall-i-build-page', 'Safety as a Garden I Tend Not a Wall I Build Page', 'act'::resource_kind, 'A values page that pictures safety as a garden tended a little each day, not a wall that must be finished before life begins.', 'Use it to help a client build safety through small daily acts instead of waiting to feel safe first.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'A wall is never high enough; a garden grows with attention. The page asks the client what their garden has in it already (people, places, routines, rooms), what they tended this week, and one small thing to plant or water tomorrow. It records what grew. Keep the page on the stabilizing side; it is about building, not recounting. Watch for the client who lists only walls; a wall around a garden is fine, as long as something grows inside.', '[{"id": "f0", "type": "textarea", "label": "What is already in my garden (people, places, routines, rooms):"}, {"id": "f1", "type": "textarea", "label": "What I tended this week, even for a minute:"}, {"id": "f2", "type": "textarea", "label": "One thing I will plant or water tomorrow:"}, {"id": "f3", "type": "textarea", "label": "What has grown that I did not notice until now:"}, {"id": "f4", "type": "textarea", "label": "The difference I feel between tending and building a wall:"}]'::jsonb, array['sexual abuse', 'values', 'safety']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('grounding-with-both-hands-flat-on-the-table-card', 'Grounding With Both Hands Flat on the Table Card', 'dbt'::resource_kind, 'A grounding card for a moment in session or at home when the body starts to leave: both palms flat on a table, pressing and naming.', 'Use it to give a client a grounding skill that needs nothing but a surface.', array['Adults', 'Teens']::text[], 'One minute, whenever needed', 'A table is almost always within reach. The card asks the client to place both palms flat, press until the forearms engage, and name five things about the surface: temperature, texture, color, edge, grain. Then one slow breath and the press released. It records when the skill was used and what came back first: the room, the sound, the breath. Keep it on the stabilizing side. Watch for the client who presses hard enough to hurt; the aim is contact, not pain.', '[{"id": "f0", "type": "textarea", "label": "Where I was, and what was happening when I noticed my body leaving:"}, {"id": "f1", "type": "textarea", "label": "Five things I named about the surface:"}, {"id": "f2", "type": "textarea", "label": "What came back first (the room, a sound, my breath):"}, {"id": "f3", "type": "textarea", "label": "How long it took, roughly:"}, {"id": "f4", "type": "textarea", "label": "Where I will use this next, and what surface will be there:"}]'::jsonb, array['sexual abuse', 'grounding', 'distress tolerance']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('coping-skills-go-bag-packing-list-sheet', 'Coping Skills Go-Bag Packing List Sheet', 'worksheet'::resource_kind, 'A packing list for a small bag of coping tools the client keeps by the door, car or desk, built like an emergency kit.', 'Use it to help a client turn the skills they know into objects they can grab.', array['Adults', 'Teens']::text[], '30 minutes to pack, then check it monthly', 'Skills that live in a notebook do not come along on a hard day; objects do. The sheet asks the client which skills work for them, what object stands for each (a smooth stone, a scent, headphones, a card with three names, a mint), what bag it goes in and where the bag lives. A monthly line checks the bag. Watch for the client who packs for every possible moment; five objects fit in a pocket and a pocket gets carried.', '[{"id": "f0", "type": "textarea", "label": "The skills that actually work for me, in a few words each:"}, {"id": "f1", "type": "textarea", "label": "One object that stands for each skill:"}, {"id": "f2", "type": "textarea", "label": "The bag, and where it lives (door, car, desk, coat pocket):"}, {"id": "f3", "type": "textarea", "label": "The card with three names and numbers, including 988 (call or text) if I ever need it:"}, {"id": "f4", "type": "textarea", "label": "The first time I reached for the bag, and what I used:"}, {"id": "f5", "type": "textarea", "label": "The day each month I will check it:"}]'::jsonb, array['coping skills', 'planning', 'skills']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('using-a-skill-means-admitting-i-am-not-okay-belief-sheet', 'Using a Skill Means Admitting I Am Not Okay Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the client who knows the skills and does not use them because reaching for one would mean they are not okay.', 'Use it to help a client test the belief that a skill is a confession.', array['Adults', 'Teens']::text[], '15 minutes', 'The skills are learned and unused, and the reason is a belief about what using one says. The sheet writes the belief and its strength, what it has cost this month to wait until things were bad enough, what the client thinks of other people who use skills early, and what reaching for one actually says about a person. The last box is one skill to use before it is needed. Watch for the client who agrees and waits for the next crisis anyway; the early use is the experiment.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words, and how much I believe it (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "What waiting until things were bad enough cost me this month:"}, {"id": "f2", "type": "textarea", "label": "What I think of other people who use a skill early:"}, {"id": "f3", "type": "textarea", "label": "What reaching for a skill actually says about a person, honestly:"}, {"id": "f4", "type": "textarea", "label": "One skill I will use this week before I need it, and when:"}, {"id": "f5", "type": "textarea", "label": "What it was like:"}]'::jsonb, array['coping skills', 'core beliefs', 'avoidance']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('coping-skill-as-an-umbrella-not-a-weather-machine-page', 'Coping Skill as an Umbrella Not a Weather Machine Page', 'act'::resource_kind, 'An acceptance page that frames a coping skill as an umbrella that keeps the client walking in the rain, not a machine that stops the rain.', 'Use it to help a client expect the right thing from a skill so they do not throw it away when it does not stop the weather.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients abandon skills that did not make the feeling go away, which was never the job. The page asks what the client expected a skill to do, what it actually did, and what an umbrella does in a storm: not dry, but moving. It asks which skills are umbrellas for them and where they were walking when they used one. Watch for the client who still wants the weather machine; name the wish kindly and come back to the walk.', '[{"id": "f0", "type": "textarea", "label": "What I expected the skill to do, honestly:"}, {"id": "f1", "type": "textarea", "label": "What it actually did:"}, {"id": "f2", "type": "textarea", "label": "What an umbrella does in a storm, and what it does not:"}, {"id": "f3", "type": "textarea", "label": "The skills that are umbrellas for me:"}, {"id": "f4", "type": "textarea", "label": "Where I was walking the last time I used one, and whether I got there:"}]'::jsonb, array['coping skills', 'acceptance', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-the-smell-of-pine-on-the-walk-card', 'Self-Soothe With the Smell of Pine on the Walk Card', 'dbt'::resource_kind, 'A Self-Soothe card for a winter walk, using the smell of pine, cold air and woodsmoke as the sense to rest in.', 'Use it to give a client an outdoor soothing skill the season hands them.', array['Adults', 'Teens']::text[], 'Fifteen minutes, on one walk', 'Winter air carries smells that most clients walk past: pine, snow, smoke, cold. The card asks the client to take one walk with smell as the only assignment, stopping at anything that reaches them and naming it, and bringing the mind back from its errands when it leaves. It records distress before and after and the smell that stayed with them. Watch for the client who turns the walk into exercise; the stopping is the skill.', '[{"id": "f0", "type": "textarea", "label": "Where I walked, and my distress before (0 to 10):"}, {"id": "f1", "type": "textarea", "label": "The smells I noticed, in order:"}, {"id": "f2", "type": "textarea", "label": "The one I stopped for longest, and what it brought to mind:"}, {"id": "f3", "type": "textarea", "label": "Where my mind went, and what brought it back:"}, {"id": "f4", "type": "textarea", "label": "My distress after (0 to 10), and the smell that stayed with me:"}]'::jsonb, array['coping skills', 'self-soothing', 'mindfulness']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('the-plane-s-turbulence-means-it-is-falling-prediction-sheet', 'The Plane''s Turbulence Means It Is Falling Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the bump mid-flight that the mind reads as the beginning of the end.', 'Use it to help a client set their in-flight prediction against what turbulence is and what happened on every past flight.', array['Adults', 'Teens']::text[], '15 minutes before the flight, then the flight', 'Turbulence is a bump in the road and feels like a fall, and the mind fills in the rest. The sheet writes the prediction and how sure the client is before boarding, what they know about turbulence from the airline and from the crew who keep serving drinks through it, and how every bumpy flight they have taken ended. On the plane, it logs the bumps and the prediction''s success rate. Watch for the client who watches the flight attendants for signs; make that a listed strategy rather than a secret one.', '[{"id": "f0", "type": "textarea", "label": "My prediction about turbulence on this flight, and how sure I am (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "What I know about what turbulence is and what the crew does during it:"}, {"id": "f2", "type": "textarea", "label": "How every bumpy flight I have taken ended:"}, {"id": "f3", "type": "textarea", "label": "On the plane: each bump, and what my mind said (a tally):"}, {"id": "f4", "type": "textarea", "label": "What my prediction got right, and what it got wrong:"}]'::jsonb, array['phobias', 'predictions', 'core CBT']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('willing-to-let-the-dog-sniff-my-hand-page', 'Willing to Let the Dog Sniff My Hand Page', 'act'::resource_kind, 'A willingness page for the moment a calm dog approaches and the client chooses to hold out a hand instead of backing away.', 'Use it to help a client make room for fear while doing one small thing toward a life with dogs in it.', array['Adults', 'Teens', 'Children']::text[], 'One encounter, plus 10 minutes after', 'Dogs are everywhere, and a life spent crossing the street to avoid them is small. The page names what the fear says will happen, what the client is willing to have in their body while a leashed, calm dog sniffs their hand, and the value it serves: visiting friends with dogs, walks in the park, a child who wants a pet. It records the encounter plainly. Choose the dog and the owner in advance. Watch for the client who wants the fear gone first; willingness goes before the hand does.', '[{"id": "f0", "type": "textarea", "label": "What my fear says will happen when the dog comes close:"}, {"id": "f1", "type": "textarea", "label": "What I am willing to feel in my body while it sniffs my hand:"}, {"id": "f2", "type": "textarea", "label": "What this is for (friends, the park, a child, something else):"}, {"id": "f3", "type": "textarea", "label": "The dog, the owner and the place, chosen in advance:"}, {"id": "f4", "type": "textarea", "label": "What actually happened, and what the dog did:"}]'::jsonb, array['phobias', 'willingness', 'exposure']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('paced-breathing-in-the-glass-elevator-card', 'Paced Breathing in the Glass Elevator Card', 'dbt'::resource_kind, 'A Paced Breathing card for the glass elevator at the mall or hotel, where the drop is visible and the ride is short.', 'Use it to give a client a breath that fits a thirty-second ride with a view of the fall.', array['Adults', 'Teens']::text[], 'One ride, repeated', 'A glass elevator shows the height the whole way and gives the fear nowhere to hide. The card sets the breath before the doors close (in for four, out for six, eyes on the floor numbers or the far wall, not the drop), and asks the client to ride one floor, then two, breathing through each. It records the ride and where the eyes went. Watch for the client who closes their eyes for the whole ride; the far wall is a step up from closed, and the view is a later step.', '[{"id": "f0", "type": "textarea", "label": "The elevator, and how many floors I will ride:"}, {"id": "f1", "type": "textarea", "label": "The breath I set before the doors close:"}, {"id": "f2", "type": "textarea", "label": "Where my eyes went during the ride:"}, {"id": "f3", "type": "textarea", "label": "My fear at the top (0 to 10), and how long it took to ease:"}, {"id": "f4", "type": "textarea", "label": "The number of floors I will ride next time:"}]'::jsonb, array['phobias', 'breathing', 'exposure']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('group-photo-request-reply-plan-sheet', 'Group Photo Request Reply Plan Sheet', 'worksheet'::resource_kind, 'A plan for the moment someone says everyone get in the picture, with the client''s choices written before the camera comes out.', 'Use it to give a client options for group photos beyond hiding in the back or leaving the room.', array['Adults', 'Teens']::text[], '15 minutes before the next gathering', 'The group photo is a small moment that many clients spend the whole gathering dreading. The sheet lists what the client usually does (hide, hold the camera, step out), what each costs them in memories and in belonging, and the choices for next time: a spot, a pose, a sentence for the person who insists, and a rule about looking at the picture afterward. Nothing here is about how the body looks. Watch for the client who plans to be the photographer every time; name it as the exit it is.', '[{"id": "f0", "type": "textarea", "label": "What I usually do when the group photo is called:"}, {"id": "f1", "type": "textarea", "label": "What that costs me (the memory, the belonging, the evening):"}, {"id": "f2", "type": "textarea", "label": "Where I will stand and what I will do with my hands next time:"}, {"id": "f3", "type": "textarea", "label": "What I will say if someone insists on retakes or comments:"}, {"id": "f4", "type": "textarea", "label": "My rule about looking at the picture afterward:"}, {"id": "f5", "type": "textarea", "label": "What the moment was actually like:"}]'::jsonb, array['body image', 'planning', 'avoidance']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('everyone-at-the-gym-is-judging-me-spotlight-sheet', 'Everyone at the Gym Is Judging Me Spotlight Sheet', 'cbt'::resource_kind, 'A spotlight-effect sheet for the client who feels every eye in the gym on them from the door to the locker room.', 'Use it to help a client test how much attention a stranger at the gym actually pays them.', array['Adults', 'Teens']::text[], 'One gym visit, plus 10 minutes after', 'The gym feels like a stage to a client who is sure they are being watched, and the belief keeps them home. The sheet writes the prediction and how sure they are, then sets the observation: how many people the client can describe after twenty minutes, how many looked up when they walked in, what everyone else was actually doing. It records the visit and the count. Nothing here is about the body itself. Watch for the client who wears headphones and eyes down the whole visit; the observation needs a glance around.', '[{"id": "f0", "type": "textarea", "label": "My prediction about who will look and what they will think, and how sure I am (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "What I noticed people actually doing when I walked in:"}, {"id": "f2", "type": "textarea", "label": "After twenty minutes: how many people I could describe, and how many could describe me:"}, {"id": "f3", "type": "textarea", "label": "How often I looked at other people''s bodies, honestly:"}, {"id": "f4", "type": "textarea", "label": "What the visit says about the spotlight:"}]'::jsonb, array['body image', 'spotlight effect', 'behavioral experiment']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-cold-wind-on-the-cheeks-not-the-mirror-card', 'Mindfulness of Cold Wind on the Cheeks Not the Mirror Card', 'dbt'::resource_kind, 'A mindfulness card that sends attention to cold wind on the face during a winter walk instead of to the mirror before leaving.', 'Use it to give a client a bodily experience that is about sensation, not appearance.', array['Adults', 'Teens']::text[], 'Ten minutes outdoors', 'The mirror before leaving the house can take twenty minutes and most of a mood. The card asks the client to leave after one look, walk outside, and give ten minutes to the cold on the cheeks, the forehead, the hands: observe it, describe it in plain words, let the mind come back from the mirror each time it wanders there. It records the mirror time before leaving and the mood after the walk. Nothing here is about how the body looks. Watch for the client who checks a phone camera on the walk; name it and return to the wind.', '[{"id": "f0", "type": "textarea", "label": "How long I spent at the mirror before leaving, honestly:"}, {"id": "f1", "type": "textarea", "label": "What the cold felt like on my cheeks, forehead and hands, in plain words:"}, {"id": "f2", "type": "textarea", "label": "How many times my mind went back to the mirror, and what brought it back:"}, {"id": "f3", "type": "textarea", "label": "My mood after the walk (0 to 10):"}, {"id": "f4", "type": "textarea", "label": "What I noticed about my body that had nothing to do with how it looked:"}]'::jsonb, array['body image', 'mindfulness', 'body awareness']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('compliments-that-land-without-appearance-pact-for-partners', 'Compliments That Land Without Appearance Pact for Partners', 'couples'::resource_kind, 'A pact where partners agree to compliment each other for a week on anything but looks, and notice what lands.', 'Use it to help a couple find praise that reaches the partner who cannot hear a word about their appearance.', array['Couples']::text[], 'One week, with a 15-minute setup', 'A partner who struggles with body image often cannot receive a compliment about their looks, and the other partner runs out of other things to say. For a week both agree to compliment only what the other did, said, chose or made: a kindness, a joke, a decision, a meal. Each keeps a short list of what they said and what they received. The debrief asks which compliment landed. Nothing here mentions the body. Watch for the partner who slips in a looks compliment as a reward; name it gently and return to the list.', '[{"id": "f0", "type": "textarea", "label": "Partner A: compliments I gave this week, none about looks:"}, {"id": "f1", "type": "textarea", "label": "Partner B: compliments I gave this week, none about looks:"}, {"id": "f2", "type": "textarea", "label": "Partner A: the one I received that landed, and why:"}, {"id": "f3", "type": "textarea", "label": "Partner B: the one I received that landed, and why:"}, {"id": "f4", "type": "textarea", "label": "What we noticed about a week without appearance in our praise:"}]'::jsonb, array['body image', 'couples', 'appreciation']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('leftover-containers-and-fridge-space-pact-for-partners', 'Leftover Containers and Fridge Space Pact for Partners', 'couples'::resource_kind, 'A pact for the week after a big meal, when one partner saves everything and the other wants the fridge back.', 'Use it to settle a small recurring kitchen fight before it stands in for a bigger one.', array['Couples']::text[], '15 minutes, then one week', 'The leftovers argument is about waste to one partner and about space and smell to the other, and both are right. Each partner says what the full fridge or the thrown-out food actually means to them. Then they agree on a rule: how many days a container lives, which shelf is for leftovers, who decides on day three, and what gets frozen instead of fought over. Watch for the partner who throws things out when the other is not home; the pact includes a say-it-first line.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what a fridge full of containers means to me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what throwing food away means to me:"}, {"id": "f2", "type": "textarea", "label": "How many days a container lives, and which shelf is theirs:"}, {"id": "f3", "type": "textarea", "label": "Who decides on the last day, and what gets frozen instead:"}, {"id": "f4", "type": "textarea", "label": "What we say before anything is thrown out:"}, {"id": "f5", "type": "textarea", "label": "After one week: what the fridge and the two of us were like:"}]'::jsonb, array['couples', 'problem solving', 'habits']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('sand-timer-wait-out-the-uh-oh-feeling-play', 'Sand Timer Wait Out the Uh-Oh Feeling Play', 'kids'::resource_kind, 'A play where a child flips a sand timer when the urge to check or redo shows up and watches the sand with a parent until it runs out.', 'Use it to give a child a visible way to wait out an urge without a lecture.', array['Children']::text[], 'Three minutes, whenever the feeling comes', 'A child who has to check or redo things needs a way to wait that they can see. The child decorates a small sand timer or a jar of glitter water, and when the uh-oh feeling comes, flips it and watches with the parent until the sand is down. The parent names nothing but what the sand is doing and what the child''s body is doing, and does not say whether to check afterward; the child reports. In session, ask what the feeling did while the sand fell. Watch for the parent who uses the timer as a rule rather than a game.', '[{"id": "f0", "type": "textarea", "label": "Decorate your timer. What does the uh-oh feeling look like when it comes?"}, {"id": "f1", "type": "textarea", "label": "Flip it. What is the feeling doing when the sand is half down?"}, {"id": "f2", "type": "textarea", "label": "What is it doing when the sand is all the way down?"}, {"id": "f3", "type": "textarea", "label": "What did you decide to do after, and how did that feel?"}, {"id": "f4", "type": "textarea", "label": "Parent: what I said while the sand fell, and what I did not say:"}]'::jsonb, array['OCD', 'children', 'play']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('lump-in-the-throat-means-i-will-choke-fact-check-sheet', 'Lump in the Throat Means I Will Choke Fact Check Sheet', 'cbt'::resource_kind, 'A fact check sheet for the tight throat during a panic surge that the mind reads as the airway closing.', 'Use it to help a client set what a tense throat does beside the choking the mind predicts.', array['Adults', 'Teens']::text[], '15 minutes', 'A tight throat makes swallowing feel like a task and the mind announces that the airway is closing. The sheet records the sensation, the thought and how sure the client was, then what they know about muscles tightening under fear, how many times this has happened, how every time ended, and whether talking or swallowing water was possible during it. The last box is the sentence for next time. Watch for the client who starts avoiding solid food in public; name that early.', '[{"id": "f0", "type": "textarea", "label": "What my throat did, and what my mind said it meant:"}, {"id": "f1", "type": "textarea", "label": "How sure I was in the moment (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I know about what fear does to the muscles of the throat:"}, {"id": "f3", "type": "textarea", "label": "How many times this has happened, how each ended, and whether I could still talk or swallow:"}, {"id": "f4", "type": "textarea", "label": "The sentence I will say to myself when the tightness starts:"}]'::jsonb, array['panic attacks', 'catastrophizing', 'core CBT']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('panic-as-a-sprinkler-system-set-off-by-steam-page', 'Panic as a Sprinkler System Set Off by Steam Page', 'act'::resource_kind, 'An acceptance page that pictures a panic surge as a building''s sprinkler system going off at kitchen steam: real water, real mess, no fire.', 'Use it to help a client let the system run and dry off without evacuating the building.', array['Adults', 'Teens']::text[], '15 minutes, then a line a day', 'A sprinkler that goes off at steam is doing its job badly, but the water is real and so is the soaking. The page asks the client to describe their system: what sets it off, how long it runs, what the soaking feels like, and what they do while it is running. Then it asks what staying in the room and waiting for the water to stop would look like this week. It records one time they stayed. Watch for the client who wants the system ripped out; the page is about getting through the shower.', '[{"id": "f0", "type": "textarea", "label": "What sets my sprinklers off, as far as I can tell:"}, {"id": "f1", "type": "textarea", "label": "What the soaking feels like, in the body, in order:"}, {"id": "f2", "type": "textarea", "label": "How long the water usually runs:"}, {"id": "f3", "type": "textarea", "label": "What staying in the room until it stops would look like this week:"}, {"id": "f4", "type": "textarea", "label": "One time I stayed, and what the room was like when the water stopped:"}]'::jsonb, array['panic attacks', 'acceptance', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('dentist-numbing-shot-step-plan-sheet', 'Dentist Numbing Shot Step Plan Sheet', 'worksheet'::resource_kind, 'A step plan for the numbing injection at the dentist, for the client who has let a tooth go rather than face the needle in the mouth.', 'Use it to help a client get needed dental work done in steps they order and choose.', array['Adults', 'Teens']::text[], '20 minutes in session, then the appointment', 'A feared dental injection keeps a lot of clients away until the tooth decides for them. The sheet breaks the appointment into steps: booking, the chair tilting back, the numbing gel, the sentence to the dentist about going slowly, the injection itself, the waiting for numbness, the work. Each gets a fear rating and the hardest gets a plan: a hand signal, counting, a foot tapping, headphones. It records the appointment. Watch for the client who plans to skip the numbing to avoid the needle; that trade is worth a conversation.', '[{"id": "f0", "type": "textarea", "label": "The work I need done, and how long I have put it off:"}, {"id": "f1", "type": "textarea", "label": "The steps in order, each with a fear rating (0 to 10):"}, {"id": "f2", "type": "textarea", "label": "The sentence I will say to the dentist before we start:"}, {"id": "f3", "type": "textarea", "label": "The hardest step, and my plan for it (signal, counting, foot tapping, headphones):"}, {"id": "f4", "type": "textarea", "label": "The actual appointment: which steps were as feared, which were not:"}, {"id": "f5", "type": "textarea", "label": "What I will tell myself at the next booking:"}]'::jsonb, array['phobias', 'exposure', 'hierarchy']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('dear-man-asking-the-landlord-to-fix-the-heat-card', 'DEAR MAN Asking the Landlord to Fix the Heat Card', 'dbt'::resource_kind, 'A DEAR MAN card for the call or message to a landlord about heat that has not worked for a week, made without rage or apology.', 'Use it to help a client make a firm, repeatable ask of someone with power over their home.', array['Adults']::text[], '20 minutes to write, then the ask', 'A cold apartment and a slow landlord bring out either fury or silence, and neither gets the heat fixed. The card scripts the ask: describe the dates and the temperature, express the effect in one sentence, assert the request with a deadline, reinforce what the landlord gains (no complaint filed, a tenant who stays), then stay mindful when they deflect, look confident, negotiate a date if not a day. It records the response and the follow-up. Watch for the client who threatens in the first sentence; the describe line comes first.', '[{"id": "f0", "type": "textarea", "label": "Describe: the dates, the temperature, the messages already sent:"}, {"id": "f1", "type": "textarea", "label": "Express: the effect on me and my household, in one sentence:"}, {"id": "f2", "type": "textarea", "label": "Assert: what I am asking for, and by when:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what they gain by fixing it this week:"}, {"id": "f4", "type": "textarea", "label": "Mindful: what I will say when they change the subject:"}, {"id": "f5", "type": "textarea", "label": "What they said, and the date I will follow up if nothing happens:"}]'::jsonb, array['DEAR MAN', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-confronting-the-coworker-today-grid', 'Pros and Cons of Confronting the Coworker Today Grid', 'dbt'::resource_kind, 'A Pros and Cons grid for the urge to confront a coworker the same afternoon something went wrong between them.', 'Use it to hold a strong urge long enough to weigh today against tomorrow and a different setting.', array['Adults']::text[], '15 minutes, before walking over', 'The urge to settle it now is strong and the afternoon is the worst possible time. The grid lays out the pros and cons of saying it today at the desk, and the pros and cons of saying it tomorrow in a booked room, including how each version lands on the coworker and on the client''s standing. The last box is the decision and the sentence that opens the conversation whenever it happens. Watch for the client whose cons of waiting are all about the feeling; name the feeling as one row, not the whole grid.', '[{"id": "f0", "type": "textarea", "label": "What happened, and what I want to say, in two lines:"}, {"id": "f1", "type": "textarea", "label": "Pros of saying it today, where we are:"}, {"id": "f2", "type": "textarea", "label": "Cons of saying it today:"}, {"id": "f3", "type": "textarea", "label": "Pros of saying it tomorrow, in a booked room:"}, {"id": "f4", "type": "textarea", "label": "Cons of waiting:"}, {"id": "f5", "type": "textarea", "label": "My decision, and the opening sentence either way:"}]'::jsonb, array['pros and cons', 'distress tolerance', 'work']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('observer-self-as-the-house-not-the-furniture-page', 'Observer Self as the House Not the Furniture Page', 'act'::resource_kind, 'A self-as-context page that places the client as the house and their thoughts, moods and roles as furniture moved around inside it.', 'Use it to help a client find a self that stays while the contents change.', array['Adults', 'Teens']::text[], '20 minutes in session, then a line a day', 'Furniture comes and goes; the house stands. The page asks the client to list the furniture of this season, the moods, the roles, the thoughts that have moved in lately, and which pieces they have mistaken for the house itself. It then asks what the house noticed as each piece arrived and what stays the same whether the room is full or empty. Watch for the client who wants to throw all the furniture out; the page is about the walls, not a clear-out.', '[{"id": "f0", "type": "textarea", "label": "The furniture in my house this season (moods, roles, thoughts that moved in):"}, {"id": "f1", "type": "textarea", "label": "The piece I have been mistaking for the whole house:"}, {"id": "f2", "type": "textarea", "label": "What the house noticed as that piece arrived:"}, {"id": "f3", "type": "textarea", "label": "What stays the same whether the room is full or empty:"}, {"id": "f4", "type": "textarea", "label": "One line I can say when a new piece of furniture arrives:"}]'::jsonb, array['self-as-context', 'core ACT', 'metaphor']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('paper-plate-mood-clock-with-a-spinning-hand-craft', 'Paper Plate Mood Clock With a Spinning Hand Craft', 'kids'::resource_kind, 'A paper-plate clock where each hour is a feeling face and a brad-fastened hand spins to show how the child feels right now.', 'Use it to give a child a way to point at a feeling before talking about it.', array['Children']::text[], '25 minutes to make, then a spin a day', 'The child draws twelve faces around a paper plate, one per hour, from calm to silly to sad to mad, and the parent fastens a cardboard hand in the center with a brad so it spins. The clock lives at child height. The parent asks what time it is on the feelings clock at the same point each day and reads the face back without fixing it. In session, spin it together and ask what moved the hand last week. Watch for the parent who sets the hand for the child.', '[{"id": "f0", "type": "textarea", "label": "Draw your twelve feeling faces. Which one is at the top?"}, {"id": "f1", "type": "textarea", "label": "What time is it on your feelings clock right now?"}, {"id": "f2", "type": "textarea", "label": "What moved the hand there today?"}, {"id": "f3", "type": "textarea", "label": "Which face do you want the hand to point at by bedtime, and what would help?"}, {"id": "f4", "type": "textarea", "label": "Parent: the time each day I ask, and what I say when my child answers:"}]'::jsonb, array['children', 'emotion identification', 'craft']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('stand-on-the-line-agree-or-disagree-game', 'Stand on the Line Agree or Disagree Game', 'game'::resource_kind, 'A movement game where a tape line runs from strongly agree to strongly disagree and players stand where they land on each statement.', 'Use it to get a group showing opinions with their feet and hearing why others stand elsewhere.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'A tape line crosses the room, agree at one end and disagree at the other. The leader reads a statement (it is okay to cry in front of friends, asking for help is a weakness, a bad morning ruins the day) and everyone stands where they land. Two players from different spots say why in one sentence each. Players may move after hearing them. Ten statements, then a debrief on which one moved people most. Watch for the player who stands in the middle every time; ask for one statement where they pick a side.', '[{"id": "f0", "type": "textarea", "label": "The statement where you stood farthest from the group, and why:"}, {"id": "f1", "type": "textarea", "label": "A reason someone gave that moved you along the line:"}, {"id": "f2", "type": "textarea", "label": "The statement where the whole group clustered, and what that says:"}, {"id": "f3", "type": "textarea", "label": "The statement you would add next time:"}, {"id": "f4", "type": "textarea", "label": "What it was like to show an opinion with your body before saying it:"}]'::jsonb, array['game', 'group', 'communication']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('losing-my-keys-again-means-i-am-hopeless-labeling-sheet', 'Losing My Keys Again Means I Am Hopeless Labeling Sheet', 'cbt'::resource_kind, 'A labeling sheet for the third lost-keys morning of the week and the one-word verdict that follows it.', 'Use it to replace a character label with a description of a solvable pattern.', array['Adults', 'Teens']::text[], '10 minutes after the next search', 'Lost keys are a logistics problem until the mind makes them a character problem. The sheet records the label, the facts (how often, where they turned up, what was happening when they were put down), what the label leaves out about the rest of the client''s day, and what the client would say about a friend who loses keys. The last box is the description that replaces the label and the one change it points to. Watch for the client who accepts the kinder description and skips the change.', '[{"id": "f0", "type": "textarea", "label": "The label my mind gave me this morning, word for word:"}, {"id": "f1", "type": "textarea", "label": "The facts: how often this week, where the keys turned up, what I was doing when I put them down:"}, {"id": "f2", "type": "textarea", "label": "What the label leaves out about the rest of my day:"}, {"id": "f3", "type": "textarea", "label": "What I would say about a friend who loses their keys this often:"}, {"id": "f4", "type": "textarea", "label": "The description that replaces the label, and the one change it points to:"}]'::jsonb, array['ADHD', 'labeling', 'thinking traps']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('mentally-replaying-the-conversation-for-harm-delay-log-sheet', 'Mentally Replaying the Conversation for Harm Delay Log Sheet', 'worksheet'::resource_kind, 'A log of the mental replay that checks a finished conversation for anything hurtful, with a growing delay before each replay.', 'Use it to help a client see mental checking as checking and stretch the gaps between replays.', array['Adults', 'Teens']::text[], 'One week of entries', 'Checking does not need hands; a conversation can be reviewed a hundred times for a harm that is never found. The log records each replay, what it was searching for, how long the client delayed before giving in, and what the replay found. The delay grows a little each day. The last box asks what a week of replays actually turned up. Watch for the client who stops replaying and starts asking the other person whether they were offended; that is the same check out loud.', '[{"id": "f0", "type": "textarea", "label": "The conversation, and the harm the replay is searching for:"}, {"id": "f1", "type": "textarea", "label": "Replay one: how soon after, and what it found:"}, {"id": "f2", "type": "textarea", "label": "Replay two: the delay I managed first, and what it found:"}, {"id": "f3", "type": "textarea", "label": "Later replays: tally, with the delay before each:"}, {"id": "f4", "type": "textarea", "label": "What a week of replays actually turned up:"}, {"id": "f5", "type": "textarea", "label": "The delay I will aim for next week:"}]'::jsonb, array['OCD', 'self-monitoring', 'intrusive thoughts']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('my-kid-runs-to-their-other-parent-first-thought-record', 'My Kid Runs to Their Other Parent First Thought Record', 'cbt'::resource_kind, 'A thought record for the moment a child runs past one parent to the other at pickup and the parent left behind writes a verdict.', 'Use it to help a parent separate a child''s moment of preference from a judgment of their bond.', array['Adults']::text[], '10 minutes after the next pickup', 'Children run to whoever they ran to yesterday, and the parent left standing feels it as a ranking. The record writes the moment, the thought, the emotion and its strength, then the evidence: who the child runs to at other moments, what the child asked for from the client this week, what preference means at this age. The balanced thought is one a parent can hold at the next pickup. Watch for the parent who starts competing for the run; name it before it starts.', '[{"id": "f0", "type": "textarea", "label": "What happened, in facts (where, who, what my child did):"}, {"id": "f1", "type": "textarea", "label": "The thought, word for word, and how much I believe it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The emotion, and how strong (0 to 10):"}, {"id": "f3", "type": "textarea", "label": "Who my child runs to at other moments this week, honestly:"}, {"id": "f4", "type": "textarea", "label": "What my child asked me for, told me, or brought me this week:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought I can hold at the next pickup:"}]'::jsonb, array['parenting', 'thought record', 'family']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('morning-routine-photo-flip-book-craft', 'Morning Routine Photo Flip Book Craft', 'kids'::resource_kind, 'A flip book of photos the child takes of each step of their own morning routine, bound with a ring and hung by the bed.', 'Use it to let a child own the morning sequence instead of being told it ten times.', array['Children']::text[], '40 minutes to make, then one flip a morning', 'A routine told by a parent is nagging; a routine shown in the child''s own photos is a plan. The child photographs each step (the toothbrush, the clothes, the backpack, the shoes) with the parent''s phone, the parent prints them, and the child orders and binds them with a ring. Each morning the child flips to the next picture and does the step; the parent points at the book instead of speaking. In session, flip through it and ask which page is hardest. Watch for the parent who takes the photos for the child.', '[{"id": "f0", "type": "textarea", "label": "Take a photo of every step of your morning. How many pages is your book?"}, {"id": "f1", "type": "textarea", "label": "Put them in order. Which step comes first, and which is last?"}, {"id": "f2", "type": "textarea", "label": "Which page is the hardest step? Draw a star on it."}, {"id": "f3", "type": "textarea", "label": "After a week: which mornings did you get to the last page?"}, {"id": "f4", "type": "textarea", "label": "Parent: what I did instead of saying the steps out loud:"}]'::jsonb, array['parenting', 'children', 'routines']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('lending-money-to-a-friend-who-has-not-paid-it-back-sheet', 'Lending Money to a Friend Who Has Not Paid It Back Sheet', 'worksheet'::resource_kind, 'A sheet for the loan to a friend that has gone quiet, with the facts, the feelings and the sentence the client could say.', 'Use it to help a client decide what to say about the money without losing the friend or the money in silence.', array['Adults', 'Teens']::text[], '20 minutes before the next time they meet', 'An unpaid loan between friends turns every coffee into a small act of not mentioning it. The sheet writes the facts (amount, date, what was said), what the client feels when they see the friend, what they want (the money, an acknowledgment, a plan), and the sentence they could say that is plain and not a trap. It then names the answers they could get and which they can live with. Watch for the client who decides to write it off to avoid the sentence; writing it off is fine if it is a choice, not an escape.', '[{"id": "f0", "type": "textarea", "label": "The facts: the amount, the date, and what we agreed:"}, {"id": "f1", "type": "textarea", "label": "What I feel when I see them now, and what I do with it:"}, {"id": "f2", "type": "textarea", "label": "What I actually want (the money, an acknowledgment, a plan, to let it go):"}, {"id": "f3", "type": "textarea", "label": "The plain sentence I could say, without a trap in it:"}, {"id": "f4", "type": "textarea", "label": "The answers I might get, and which ones I can live with:"}, {"id": "f5", "type": "textarea", "label": "My decision, and when:"}]'::jsonb, array['relationship issues', 'money', 'communication']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('where-my-body-tells-me-uh-oh-drawing-craft', 'Where My Body Tells Me Uh-Oh Drawing Craft', 'kids'::resource_kind, 'A body outline a child colors to show where the uh-oh feeling lives, with a parent naming it as a signal to go tell someone.', 'Use it to help a child notice their body''s warning feeling and connect it to telling a safe grown-up.', array['Children']::text[], '25 minutes', 'Children often feel that something is wrong before they have the words for it. The child traces or is given a body outline and colors where the uh-oh feeling shows up (tummy, chest, throat, legs that want to run) and picks a color for it. The parent names it as the body''s way of saying go tell someone, and together they write who. The activity stays on the safety side and asks nothing about any event. Remember your reporting duties if a child discloses while coloring.', '[{"id": "f0", "type": "textarea", "label": "Color where the uh-oh feeling lives in your body. What color is it?"}, {"id": "f1", "type": "textarea", "label": "What does it feel like there (buzzy, heavy, tight, wiggly)?"}, {"id": "f2", "type": "textarea", "label": "When your body says uh-oh, who can you go tell? Write or draw them."}, {"id": "f3", "type": "textarea", "label": "What will you say to them first?"}, {"id": "f4", "type": "textarea", "label": "Parent: what I said about the uh-oh feeling, and the names we wrote down:"}]'::jsonb, array['sexual abuse', 'children', 'body awareness']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('brave-fox-visits-the-automatic-hand-dryer-play', 'Brave Fox Visits the Automatic Hand Dryer Play', 'kids'::resource_kind, 'A play scene where a child''s stuffed fox approaches the restroom hand dryer in steps, from the doorway to a paw under the air.', 'Use it to help a child get through a loud public restroom with a toy that goes first.', array['Children']::text[], '15 minutes, several outings', 'The hand dryer sends some children out of public restrooms with wet hands and a racing heart. The fox goes first: the child holds it in the doorway while someone else uses the dryer, then on the sink, then under the dryer while it is off, then the child presses the button for one second with the fox held close. The child says when to stop at every step. In session, ask what the fox found out. Watch for the parent who presses the button early; the child owns the steps.', '[{"id": "f0", "type": "textarea", "label": "Where does Brave Fox stand first? Draw the restroom."}, {"id": "f1", "type": "textarea", "label": "What does Fox notice when someone else uses the dryer?"}, {"id": "f2", "type": "textarea", "label": "When is Fox ready to go under the air? You say when."}, {"id": "f3", "type": "textarea", "label": "What does Fox tell you about the noise afterward?"}, {"id": "f4", "type": "textarea", "label": "Parent: the steps my child chose, and the moment I waited for their word:"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('build-mastery-by-cooking-breakfast-on-a-sober-saturday-card', 'Build Mastery by Cooking Breakfast on a Sober Saturday Card', 'dbt'::resource_kind, 'A Build Mastery card for the first Saturday mornings without substance use, using a real cooked breakfast as the day''s first accomplishment.', 'Use it to give a client a morning that proves something small before the day''s urges arrive.', array['Adults']::text[], 'One Saturday morning, repeated', 'Saturday mornings in early recovery are often empty hours that used to be lost, and empty hours invite urges. The card sets a breakfast the client has to actually make, eggs and toast or pancakes, not cereal, and asks them to notice the steps, the smell, the plate, and the feeling of having done one thing well before nine. It records the mood after and the urge level through the morning. Watch for the client who scores the breakfast on how it tasted; the mastery is in the making.', '[{"id": "f0", "type": "textarea", "label": "What I will cook, and what I need to buy on Friday:"}, {"id": "f1", "type": "textarea", "label": "My mood when I woke up (0 to 10), and the urge level:"}, {"id": "f2", "type": "textarea", "label": "The steps I noticed while cooking, and the moment it smelled like breakfast:"}, {"id": "f3", "type": "textarea", "label": "My mood after eating (0 to 10), and the urge level by noon:"}, {"id": "f4", "type": "textarea", "label": "What I did with the rest of the morning:"}]'::jsonb, array['addiction', 'build mastery', 'routines']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('guess-the-coping-skill-from-three-clues-game', 'Guess the Coping Skill From Three Clues Game', 'game'::resource_kind, 'A guessing game where one player gives three clues about a coping skill without naming it and the group races to say which skill it is.', 'Use it to get a group recalling and describing skills in their own words under a little pressure.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Players draw a skill card (paced breathing, a cold face splash, calling a friend, a walk around the block, writing the thought down). The drawer gives three clues, one at a time, without saying the skill''s name: where you might do it, what it feels like, when it helps. The group guesses after each clue; a guess on the first clue earns three points, the second two, the third one. The debrief asks which skill needed all three clues and why. Watch for the player who gives the name inside the clue; a gentle redo keeps the game going.', '[{"id": "f0", "type": "textarea", "label": "The skill you drew, and your three clues:"}, {"id": "f1", "type": "textarea", "label": "The skill you guessed fastest, and what gave it away:"}, {"id": "f2", "type": "textarea", "label": "The skill nobody guessed until the third clue:"}, {"id": "f3", "type": "textarea", "label": "A skill described today in a way that made you want to try it:"}, {"id": "f4", "type": "textarea", "label": "Which skill from the deck you will actually use this week:"}]'::jsonb, array['coping skills', 'game', 'group']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('values-under-the-winter-layers-page', 'Values Under the Winter Layers Page', 'act'::resource_kind, 'A values page for the months of coats and scarves, when appearance recedes and the client can notice what they do with their body.', 'Use it to help a client find the life they want their body for when how it looks is off the table.', array['Adults', 'Teens']::text[], '15 minutes, then a line a week', 'Winter layers take appearance off the table for a few months, and some clients breathe for the first time all year. The page asks what the client has done with their body under the layers (walked, carried, danced, sat with someone) and what they want more of before spring, when the commentary comes back. It asks what the layers make possible and whether any of it depends on the coat. Nothing here is about how the body looks or changing it. Watch for the client who dreads spring already; write that down and keep it for the warmer months.', '[{"id": "f0", "type": "textarea", "label": "What I have done with my body under the layers this week:"}, {"id": "f1", "type": "textarea", "label": "What the coat makes easier, honestly:"}, {"id": "f2", "type": "textarea", "label": "What I want more of before spring, in doing, not looking:"}, {"id": "f3", "type": "textarea", "label": "Which of those depends on the coat, and which does not:"}, {"id": "f4", "type": "textarea", "label": "One thing I will do this week that I would do in any season:"}]'::jsonb, array['body image', 'values', 'committed action']::text[], '2026-11-27T15:00:00+00:00'::timestamptz),
  ('paper-fortune-teller-calm-thought-pick-game', 'Paper Fortune Teller Calm Thought Pick Game', 'game'::resource_kind, 'A folded paper fortune teller where every flap hides a calming sentence the group wrote, played in pairs when a worry comes up.', 'Use it to let a group write its own calming lines and hand them to each other by chance.', array['Groups', 'Teens', 'Children']::text[], '25 minutes to make and play', 'Each pair folds a paper fortune teller and writes eight calming sentences under the flaps, two from each of four categories the leader names: a fact, a kind line, a question, a thing to do. Then one player names a worry in a sentence, the other works the fortune teller by the worry''s word count and reads the hidden line aloud, and they talk for one minute about whether it fit. Swap roles. The debrief asks which line the group wants to keep. Watch for pairs whose lines are all advice; the fact and the question categories are there for that reason.', '[{"id": "f0", "type": "textarea", "label": "The eight lines your pair wrote, two per category:"}, {"id": "f1", "type": "textarea", "label": "The worry you named, and the line the fortune teller gave you:"}, {"id": "f2", "type": "textarea", "label": "Did it fit? What would have fit better?"}, {"id": "f3", "type": "textarea", "label": "The line from another pair that the group wanted to keep:"}, {"id": "f4", "type": "textarea", "label": "Where could a fortune teller like this live in your week?"}]'::jsonb, array['anxiety', 'game', 'group']::text[], '2026-11-27T15:00:00+00:00'::timestamptz)
